// Original source: rtl/hdc/ot_hdc_prefix.sv
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// Explicit log-depth adders (W10, 72f00b86; shared FP primitive copy owned by W11, rtl/hdc/ot_hdc_prefix.sv).
//
// Written as behavioural `a + b` or `a + inc`, yosys/ABC maps these adders as carry ripples (chains of MAJ or
// OR cells) even with ADDER_MAP_FILE cleared: measured at ORFS WC, 0.833 ns, a 28-bit add inside the element
// took 920 ps and a 24-bit rounding increment a chain of ten OR4/OR5 cells (W10 and W13, 2026-09-30).  Here each
// Kogge-Stone prefix level is a (* keep *) net, so_pooln synthesis must keep log2(W) levels.
//
// ot_v41_ksadd: s = a + b + cin (W bits), cout.
// ot_v41_inc:   y = a + inc (W bits), co (the carry out of the top bit).
// ---------------------------------------------------------------------------
module ot_hdc_ksadd_k_pooln #(
    parameter integer W = 28
) (
    input  wire [W-1:0] a,
    input  wire [W-1:0] b,
    input  wire         cin,
    output wire [W-1:0] s,
    output wire         cout
);
    localparam integer L = $clog2(W + 1);
    // position 0 is the carry-in; bit i of the operands is position i + 1
    (* keep *) wire [W:0] g [0:L];
    (* keep *) wire [W:0] p [0:L];
    assign g[0] = {a & b, cin};
    assign p[0] = {a ^ b, 1'b0};
    genvar l, i;
    generate
        for (l = 0; l < L; l = l + 1) begin : g_lv
            for (i = 0; i <= W; i = i + 1) begin : g_b
                if (i >= (1 << l)) begin : g_c
                    assign g[l + 1][i] = g[l][i] | (p[l][i] & g[l][i - (1 << l)]);
                    assign p[l + 1][i] = p[l][i] & p[l][i - (1 << l)];
                end else begin : g_p
                    assign g[l + 1][i] = g[l][i];
                    assign p[l + 1][i] = p[l][i];
                end
            end
        end
    endgenerate
    // carry into operand bit i = the group generate of positions [0, i]
    assign s = (a ^ b) ^ g[L][W-1:0];
    assign cout = g[L][W];
endmodule


module ot_hdc_inc_k_pooln #(
    parameter integer W = 24
) (
    input  wire [W-1:0] a,
    input  wire         inc,
    output wire [W-1:0] y,
    output wire         co
);
    localparam integer L = $clog2(W + 1);
    // t[i]: all of positions [0, i] are one, position 0 being the increment
    (* keep *) wire [W:0] t [0:L];
    assign t[0] = {a, inc};
    genvar l, i;
    generate
        for (l = 0; l < L; l = l + 1) begin : g_lv
            for (i = 0; i <= W; i = i + 1) begin : g_b
                if (i >= (1 << l)) begin : g_c
                    assign t[l + 1][i] = t[l][i] & t[l][i - (1 << l)];
                end else begin : g_p
                    assign t[l + 1][i] = t[l][i];
                end
            end
        end
    endgenerate
    assign y = a ^ t[L][W-1:0];
    assign co = t[L][W];
endmodule

// Original source: rtl/hdc/v41x/ot_dsrom_fp32_add_l6.sv
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// DS-ROM recovery lever su_norm: the 1.2 GHz binary32 adder with SIX stages, ot_hdc_fp32_add_f12_pooln (rtl/hdc/
// ot_hdc_fp32_f12.sv, unchanged) at CUTS 7'b1101011: decode + exponent differences | magnitude compare |
// alignments + swap | sum + LZC | cancellation shift + round | encode.  The l5x adder (7'b1101010) keeps the
// compare, both alignments and the swap in one stage; routed inside the fused norm pipeline that stage measured
// 764 ps of logic (SS -14 / -33 ps, routes mix1_a / mix1_b), so_pooln cut 0 splits it (owner closure procedure: a
// stage after a second miss).  Bit for bit the same function (only register boundaries move; equivalence:
// rtl/test/tb_dsrom_fp32_add_l6.sv against ot_hdc_fp32_add_fast_pooln delayed by 3).
// ---------------------------------------------------------------------------
module ot_dsrom_fp32_add_f12_l6_pooln (input wire clk, rst_n, valid_in, input wire [31:0] a, b, output wire [31:0] y,
                                 output wire [1:0] err, output wire valid_out);
    ot_hdc_fp32_add_f12_pooln #(.CUTS(7'b1101011)) u (.*);
endmodule

// Original source: rtl/hdc/ot_hdc_fastfp_lat_f12.sv
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// hbm-fmax-su (2026-10-04): the 1.2 GHz FILE SWAP of rtl/hdc/ot_hdc_fastfp_lat.sv -- the same modules (ot_hdc_qmul_lat_pooln,
// ot_hdc_qadd_lat_pooln, ot_hdc_kadd_pooln / _kge / _kinc) with the serial-domain latencies mapped to the units that close
// 0.833 ns at ASAP7 SS (rtl/hdc/ot_hdc_fp32_f12.sv): the multiplier at LAT 5 / 6 is ot_hdc_fp32_mul_f12_l5_pooln / _l6,
// the keep-prefix adder at LAT 4 / 5 is ot_hdc_fp32_add_f12_l4_pooln / _l5x (cut after the decode / exponent differences).  Same function, same latency, so_pooln a unit
// built from either file is cycle- and bit-identical (rtl/test/tb_su_fp32_f12.sv).  A source list names_pooln this
// file OR the original, never both; the original (pinned by committed records) is unchanged.
// Needs rtl/hdc/ot_hdc_fp32_f12.sv besides the original's dependencies.
// ---------------------------------------------------------------------------
// ot_hdc_qmul_lat_pooln #(LAT): ot_hdc_qmul_pooln with the multiplier's latency as a parameter.  LAT = 3 is ot_hdc_qmul_pooln
// itself (ot_hdc_fp32_mul_fast_pooln); LAT = 4..7 is ot_hdc_fp32_mul_lat_pooln #(LAT) (rtl/hdc/ot_hdc_fp32_mul_lat_pooln.sv, which
// needs rtl/hdc/ot_hdc_fp32_add_lat_pooln.sv), bit-identical to it (21d9aab2: 5,000,000 biased pairs).  W11 serial
// domain: the 3-stage multiply misses 1.111 ns at SS; LAT 4 reaches 987 MHz.
module ot_hdc_qmul_lat_pooln #(
    parameter integer LAT = 3
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output wire [31:0] y,
    output wire        fault
);
    wire [1:0] err;
    wire vo;
    generate if (LAT == 3) begin : g_l3
        ot_hdc_fp32_mul_fast_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
    end else if (LAT == 4) begin : g_l4
        // the fixed LAT-4 top: a plain module name_pooln, so_pooln synthesis can keep it as its own hierarchy
        // (ORFS SYNTH_KEEP_MODULES) and ABC maps it as the standalone unit
        ot_hdc_fp32_mul_lat4_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
    end else if (LAT == 5) begin : g_l5
        // 1.2 GHz: decode..normalise | rows + 5 CSA | 2 CSA + 48-bit add | select / subnormal | round + encode
        ot_hdc_fp32_mul_f12_l5_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
    end else if (LAT == 6) begin : g_l6
        // 1.2 GHz lane build: the lane's operand multiplexer + decode + fraction LZC | normalise, powers | rows + 5 CSA |
        // 2 CSA + 48-bit add | select / subnormal | round + encode (an input register in front of the LAT-5 unit
        // missed by 12 ps: its decode / LZC / normalise stage is the longest)
        ot_hdc_fp32_mul_f12_l6_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
    end else begin : g_ln
        ot_hdc_fp32_mul_lat_pooln #(.LAT(LAT)) u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err),
                                            .valid_out(vo));
    end endgenerate
    assign fault = vo && (err != 2'd0);
endmodule

// ot_hdc_qadd_lat_pooln #(KEEP, LAT): ot_hdc_qadd_pooln, or (KEEP = 1) the plain ot_hdc_fp32_add_lat3_pooln top of
// rtl/hdc/ot_hdc_fp32_add_lat_pooln.sv (needs rtl/hdc/ot_hdc_prefix.sv): the same binary32 add, bit for bit, with
// (* keep *) Kogge-Stone prefix adders that ABC cannot re-ripple inside a parent block; LAT = 4 (KEEP = 1) is
// the input-cut ot_hdc_fp32_add_lat4i_pooln (W11 serial domain, 0.9 GHz at SS).
module ot_hdc_qadd_lat_pooln #(
    parameter integer KEEP = 0,
    parameter integer LAT = 3
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output wire [31:0] y,
    output wire        fault
);
    wire [1:0] err;
    wire vo;
    generate if (KEEP == 0) begin : g_fast
        ot_hdc_fp32_add_fast_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
    end else if (KEEP == 2 && LAT == 5) begin : g_keep5s
        // S81-RERUN margin build: the LAT-4 cut set plus a cut between the sum and the renormalise / leading-zero
        // count (CUTS bit 2): the exp polynomial's add + LZC stage was the swiglu lane's only SS miss (-10 ps at 0.833)
        ot_hdc_fp32_add_f12_l5s_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
    end else if (LAT == 4) begin : g_keep4
        // 1.2 GHz: decode..swap | add + LZC | shift + round | encode
        ot_hdc_fp32_add_f12_l4_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
    end else if (LAT == 5) begin : g_keep5
        // 1.2 GHz lane build: the lane's operand multiplexer + decode + exponent differences | compare, alignments,
        // swap | add, LZC | shift, round | encode (an input register in front of the LAT-4 unit missed by 21-50 ps)
        ot_hdc_fp32_add_f12_l5x_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
    end else if (LAT == 3) begin : g_keep
        ot_hdc_fp32_add_lat3_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
    end else begin : g_keepn
        ot_hdc_fp32_add_lat_pooln #(.LAT(LAT)) u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err),
                                            .valid_out(vo));
    end endgenerate
    assign fault = vo && (err != 2'd0);
endmodule

// Keep-prefix integer arithmetic for the W11 serial-domain build (K = 1: rtl/hdc/ot_hdc_prefix.sv, whose
// (* keep *) Kogge-Stone levels ABC cannot re-ripple; K = 0: the behavioural operator, the unit as it was).
module ot_hdc_kadd_pooln #(parameter integer W = 24, parameter integer K = 0) (
    input  wire [W-1:0] a, input wire [W-1:0] b, input wire cin, output wire [W-1:0] s, output wire cout
);
    generate if (K == 0) begin : g_b
        assign {cout, s} = {1'b0, a} + {1'b0, b} + {{W{1'b0}}, cin};
    end else begin : g_k
        ot_hdc_ksadd_k_pooln #(.W(W)) u (.a(a), .b(b), .cin(cin), .s(s), .cout(cout));
    end endgenerate
endmodule

// ge = (a >= b), unsigned
module ot_hdc_kge_pooln #(parameter integer W = 32, parameter integer K = 0) (
    input  wire [W-1:0] a, input wire [W-1:0] b, output wire ge
);
    generate if (K == 0) begin : g_b
        assign ge = (a >= b);
    end else begin : g_k
        wire [W-1:0] unused_s;
        ot_hdc_ksadd_k_pooln #(.W(W)) u (.a(a), .b(~b), .cin(1'b1), .s(unused_s), .cout(ge));
    end endgenerate
endmodule

// y = a + inc (mod 2^W)
module ot_hdc_kinc_pooln #(parameter integer W = 16, parameter integer K = 0) (
    input  wire [W-1:0] a, input wire inc, output wire [W-1:0] y
);
    generate if (K == 0) begin : g_b
        assign y = a + {{(W-1){1'b0}}, inc};
    end else begin : g_k
        wire unused_co;
        ot_hdc_inc_k_pooln #(.W(W)) u (.a(a), .inc(inc), .y(y), .co(unused_co));
    end endgenerate
endmodule

// Original source: rtl/hdc/ot_hdc_sfu.sv
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// Special-function pipelines of the hardwired decode core: exp, reciprocal and
// reciprocal square root.  Each is an unrolled chain of the qualified binary32
// multiply/add pipes (LATENCY 5, II 1) plus single-cycle integer steps, so_pooln each
// accepts one operand per cycle and returns it a fixed DEPTH later.  No divider,
// no iteration, no combinational IEEE operation.
//
// The algorithms and their operation order are the specification in
// tools/hdc_golden.py (exp, reciprocal, rsqrt); the RTL matches it bit for bit.
// ---------------------------------------------------------------------------

// Valid delay line with a tap per stage (vd[k] = v delayed k cycles).
module ot_hdc_vline_pooln #(parameter integer D = 1) (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       v,
    output wire [D:0] vd
);
    wire [(D+15)/16-1:0] reset_leaf;
    ot_pool_reset_tree #(.N((D+15)/16),.ID(2)) u_reset(clk,rst_n,reset_leaf);
    (* keep *) reg [D:1] line;
    for(genvar q=1;q<=D;q=q+1) begin:g_valid
      if(q==1) begin:g_first
       always @(posedge clk or negedge reset_leaf[(q-1)/16])
        if(!reset_leaf[(q-1)/16]) line[q]<=1'b0; else line[q]<=v;
      end else begin:g_next
       always @(posedge clk or negedge reset_leaf[(q-1)/16])
        if(!reset_leaf[(q-1)/16]) line[q]<=1'b0; else line[q]<=line[q-1];
      end
    end
    assign vd = {line, v};
endmodule

// exp(x): clamp to [-87, 88]; n = rint(x*log2e) by the 1.5*2^23 trick; two-
// constant Cody-Waite reduction; degree-6 Horner; 2^n added to the exponent.
module ot_hdc_exp_pooln (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    (* keep *) output reg  [31:0] y,
    output wire        vo,
    output wire        fault
);
    localparam integer DEPTH = 92;
    localparam [31:0] K_MAX   = 32'h42B00000;   //  88.0
    localparam [31:0] K_MINM  = 32'h42AE0000;   //  87.0 (magnitude of the lower clamp)
    localparam [31:0] K_LOG2E = 32'h3FB8AA3B;
    localparam [31:0] K_MAGIC = 32'h4B400000;   //  1.5 * 2^23
    localparam [31:0] K_NMAGIC = 32'hCB400000;
    localparam [31:0] K_HI    = 32'h3F317200;   //  ln2 high part
    localparam [31:0] K_LO    = 32'h35BFBE8E;   //  ln2 low part
    localparam [32*7-1:0] POLY = {32'h3AB60B61, 32'h3C088889, 32'h3D2AAAAB,
                                  32'h3E2AAAAB, 32'h3F000000, 32'h3F800000, 32'h3F800000};
    function automatic [31:0] poly(input integer i);   // EXP_POLY[i]
        poly = POLY[32*(6-i) +: 32];
    endfunction

    wire [DEPTH:0] vd;
    ot_hdc_vline_pooln #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    // depth 1: clamp
    (* keep *) reg [31:0] xc;
    always @(posedge clk) begin
        if (!x[31] && x[30:0] > K_MAX[30:0]) xc <= K_MAX;
        else if (x[31] && x[30:0] > K_MINM[30:0]) xc <= {1'b1, K_MINM[30:0]};
        else xc <= x;
    end

    wire [31:0] t, u, n, a_hi, a_lo, r1, r, xc_d20, lo_d5;
    wire [6:0] f;
    ot_hdc_fmul m_t  (clk, rst_n, vd[1],  xc, K_LOG2E, t,   f[0]);   // 6
    ot_hdc_fadd a_u  (clk, rst_n, vd[6],  t,  K_MAGIC, u,   f[1]);   // 11
    ot_hdc_fadd a_n  (clk, rst_n, vd[11], u,  K_NMAGIC, n,  f[2]);   // 16
    ot_hdc_fmul m_hi (clk, rst_n, vd[16], n,  K_HI,    a_hi, f[3]);  // 21
    ot_hdc_fmul m_lo (clk, rst_n, vd[16], n,  K_LO,    a_lo, f[4]);  // 21
    ot_hdc_delay_pooln #(.W(32), .D(20)) d_x (clk, rst_n, xc, xc_d20);
    ot_hdc_fadd a_r1 (clk, rst_n, vd[21], xc_d20, {~a_hi[31], a_hi[30:0]}, r1, f[5]);  // 26
    ot_hdc_delay_pooln #(.W(32), .D(5)) d_lo (clk, rst_n, a_lo, lo_d5);
    ot_hdc_fadd a_r  (clk, rst_n, vd[26], r1, {~lo_d5[31], lo_d5[30:0]}, r, f[6]);     // 31

    // Horner: p = C0; six times p = p*r + C[k]; r travels in 10-cycle hops.
    wire [31:0] rd [0:6];
    wire [31:0] pm [1:6];
    wire [31:0] pa [0:6];
    wire [12:1] hf;
    assign rd[0] = r;
    assign pa[0] = poly(0);
    genvar k;
    generate
        for (k = 1; k <= 6; k = k + 1) begin : g_h
            if (k < 6) begin : g_rd
                ot_hdc_delay_pooln #(.W(32), .D(10)) d_r (clk, rst_n, rd[k-1], rd[k]);
            end
            ot_hdc_fmul u_m (clk, rst_n, vd[31 + 10*(k-1)], pa[k-1], rd[k-1], pm[k], hf[2*k-1]);
            ot_hdc_fadd u_a (clk, rst_n, vd[36 + 10*(k-1)], pm[k], poly(k), pa[k], hf[2*k]);
        end
    endgenerate

    // n as an integer: u = 1.5*2^23 + n exactly, so_pooln n sits in u's fraction.
    (* keep *) reg  [8:0] nint;
    wire [8:0] nint_d;
    always @(posedge clk) nint <= u[8:0];   // low 9 bits of 0x400000 + n are n
    ot_hdc_delay_pooln #(.W(9), .D(79)) d_n (clk, rst_n, nint, nint_d);   // 12 -> 91
    always @(posedge clk) y <= pa[6] + {{14{nint_d[8]}}, nint_d, 23'd0};   // 92

    assign fault = |{f, hf};
endmodule

// 1/d: seed 0x7ef311c7 - bits(d), three Newton-Raphson steps y*(2 - d*y).
module ot_hdc_recip_pooln (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    output wire [31:0] y,
    output wire        vo,
    output wire        fault
);
    localparam integer DEPTH = 46;
    wire [DEPTH:0] vd;
    ot_hdc_vline_pooln #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    (* keep *) reg [31:0] y0, d1;
    always @(posedge clk) begin
        // The bit seed wraps above this finite positive denominator.
        // Saturate that unsupported range to +0 before Newton iteration.
        y0 <= (!x[31] && x[30:23] != 8'hff && x > 32'h7EF311C7)
            ? 32'h00000000 : 32'h7EF311C7 - x;
        d1 <= x;
    end
    wire [31:0] yi [0:3];
    wire [31:0] dd [0:2];
    wire [31:0] m [0:2];
    wire [31:0] s [0:2];
    wire [31:0] yd [0:2];
    wire [8:0] f;
    assign yi[0] = y0;
    assign dd[0] = d1;
    genvar k;
    generate
        for (k = 0; k < 3; k = k + 1) begin : g_nr
            if (k < 2) begin : g_d
                ot_hdc_delay_pooln #(.W(32), .D(15)) d_d (clk, rst_n, dd[k], dd[k+1]);
            end
            ot_hdc_fmul m_m (clk, rst_n, vd[1 + 15*k], dd[k], yi[k], m[k], f[3*k]);
            ot_hdc_fadd a_s (clk, rst_n, vd[6 + 15*k], 32'h40000000, {~m[k][31], m[k][30:0]}, s[k], f[3*k+1]);
            ot_hdc_delay_pooln #(.W(32), .D(10)) d_y (clk, rst_n, yi[k], yd[k]);
            ot_hdc_fmul m_y (clk, rst_n, vd[11 + 15*k], yd[k], s[k], yi[k+1], f[3*k+2]);
        end
    endgenerate
    assign y = yi[3];
    assign fault = |f;
endmodule

// 1/sqrt(v): seed 0x5f3759df - (bits >> 1), three steps y*(1.5 - half*(y*y)).
module ot_hdc_rsqrt_pooln (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    output wire [31:0] y,
    output wire        vo,
    output wire        fault
);
    localparam integer DEPTH = 61;
    wire [DEPTH:0] vd;
    ot_hdc_vline_pooln #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    (* keep *) reg [31:0] y0;
    always @(posedge clk) y0 <= 32'h5F3759DF - {1'b0, x[31:1]};
    wire [31:0] half;
    wire [31:0] hd [0:2];
    wire [31:0] yi [0:3];
    wire [31:0] yy [0:2];
    wire [31:0] hm [0:2];
    wire [31:0] s [0:2];
    wire [31:0] yd [0:2];
    wire [12:0] f;
    ot_hdc_fmul m_half (clk, rst_n, v, x, 32'h3F000000, half, f[12]);   // 5
    ot_hdc_delay_pooln #(.W(32), .D(1)) d_h0 (clk, rst_n, half, hd[0]);       // 6
    assign yi[0] = y0;
    genvar k;
    generate
        for (k = 0; k < 3; k = k + 1) begin : g_nr
            if (k < 2) begin : g_h
                ot_hdc_delay_pooln #(.W(32), .D(20)) d_h (clk, rst_n, hd[k], hd[k+1]);
            end
            ot_hdc_fmul m_yy (clk, rst_n, vd[1 + 20*k],  yi[k], yi[k], yy[k], f[4*k]);
            ot_hdc_fmul m_hm (clk, rst_n, vd[6 + 20*k],  hd[k], yy[k], hm[k], f[4*k+1]);
            ot_hdc_fadd a_s  (clk, rst_n, vd[11 + 20*k], 32'h3FC00000, {~hm[k][31], hm[k][30:0]}, s[k], f[4*k+2]);
            ot_hdc_delay_pooln #(.W(32), .D(15)) d_y (clk, rst_n, yi[k], yd[k]);
            ot_hdc_fmul m_y  (clk, rst_n, vd[16 + 20*k], yd[k], s[k], yi[k+1], f[4*k+3]);
        end
    endgenerate
    assign y = yi[3];
    assign fault = |f;
endmodule

// Original source: rtl/hdc/ot_hdc_delay.sv
`timescale 1ns/1ps
// Fixed delay line: q is d delayed by D cycles (D = 0 is a wire).  Data lines
// carry no reset -- validity travels on a separate, reset delay line -- so_pooln a
// wide operand costs flops and no reset fan-out.
module ot_hdc_delay_pooln #(
    parameter integer W = 32,
    parameter integer D = 1,
    parameter integer RESET = 0
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [W-1:0] d,
    output wire [W-1:0] q
);
    generate
        if (D == 0) begin : g_wire
            assign q = d;
        end else if (D == 1) begin : g_one
            (* keep *) reg [W-1:0] line;
            if (RESET != 0) begin : g_rst
                always @(posedge clk or negedge rst_n)
                    if (!rst_n) line <= {W{1'b0}};
                    else line <= d;
            end else begin : g_nrst
                always @(posedge clk) line <= d;
            end
            assign q = line;
        end else begin : g_line
            (* keep *) reg [W*D-1:0] line;
            if (RESET != 0) begin : g_rst
                always @(posedge clk or negedge rst_n)
                    if (!rst_n) line <= {(W*D){1'b0}};
                    else line <= {line[W*(D-1)-1:0], d};
            end else begin : g_nrst
                always @(posedge clk) line <= {line[W*(D-1)-1:0], d};
            end
            assign q = line[W*D-1 -: W];
        end
    endgenerate
endmodule

// Original source: rtl/hdc/v41x/ot_hdc_v41x_sfu.sv
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// Special-function pipes of the V4.1 vector stream unit (ot_hdc_v41x_vec), at
// the fast-FP depths and with NO padding:
//
//   ot_hdc_v41x_exp_pooln       exp(x), DEPTH 49     } verbatim copies of ot_hdc_exp_pooln and
//   ot_hdc_v41x_rsqrt_pooln     1/sqrt(x), DEPTH 37  } ot_hdc_rsqrt_pooln in rtl/hdc/ot_hdc_sfu.sv
//                                                on branch worktree-agent-a516a664e7d53536c
//                                                (acc46e61), renamed only.  The
//                                                main-line file keeps the five-stage
//                                                pipes under the old names_pooln.  Their
//                                                algorithms are tools/hdc_golden.py
//                                                exp and rsqrt, checked there on all
//                                                2^32 inputs.
//   ot_hdc_v41x_fdiv_pooln      IEEE binary32 division, DEPTH 19 (rtl/hdc/v41/ot_hdc_fdiv's
//                         digit recurrence, two quotient bits per stage, radix-4 select)
//   ot_hdc_v41x_softplus_pooln  softplus and sqrt(softplus), DEPTH 162
//   ot_hdc_v41x_ins_pooln       an insertion delay line: variable depth, in order
//
// They are built from the fast binary32 add and multiply (rtl/hdc/ot_hdc_fastfp.sv:
// LATENCY 3, II 1), which are bit-identical to the qualified five-stage pipes.
// ---------------------------------------------------------------------------

// exp(x): clamp to [-87, 88]; t = x*log2e; n = rint(t); two-constant Cody-Waite
// reduction; degree-6 Horner; 2^n added to the exponent.
//
// The golden forms n by the 1.5*2^23 trick: u = t + 1.5*2^23 is the exact sum
// rounded to an integer, ties to even (|t| < 2^22 puts u in [2^23, 2^24), where
// the ulp is 1, and 1.5*2^23 is even), and n = u - 1.5*2^23 is exact.  That is
// rint-to-even of t, so_pooln here it is one integer step on t's encoding.  n*ln2_hi
// (exact) and RN(n*ln2_lo) depend on n alone, n in [-126, 127] after the clamp:
// a 254-entry table holding the golden's own products.
module ot_hdc_v41x_exp_pooln #(
    parameter integer LM = 3,                   // multiplier latency (ot_hdc_qmul_lat_pooln)
    parameter integer LA = 3                    // add latency (ot_hdc_qadd_lat_pooln: 3, or 4 input cut)
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    (* keep *) output reg  [31:0] y,
    output wire        vo,
    output wire        fault
);
    wire [9:0] exp_reset;
    ot_pool_reset_tree #(.N(10),.ID(3)) u_reset(clk,rst_n,exp_reset);
    localparam integer T_N = 1 + LM + 1;        // n registered
    localparam integer T_K = T_N + 1;           // table products registered
    localparam integer T_R1 = T_K + LA;
    localparam integer T_R = T_R1 + LA;
    localparam integer T_P = T_R + 6 * (LM + LA);
    localparam integer DEPTH = T_P + 1;         // 7 LM + 8 LA + 4: 49 (LM 3), 56 (LM 4)
    localparam [31:0] K_MAX   = 32'h42B00000;   //  88.0
    localparam [31:0] K_MINM  = 32'h42AE0000;   //  87.0 (magnitude of the lower clamp)
    localparam [31:0] K_LOG2E = 32'h3FB8AA3B;
    localparam [32*7-1:0] POLY = {32'h3AB60B61, 32'h3C088889, 32'h3D2AAAAB,
                                  32'h3E2AAAAB, 32'h3F000000, 32'h3F800000, 32'h3F800000};
    function automatic [31:0] poly(input integer i);   // EXP_POLY[i]
        poly = POLY[32*(6-i) +: 32];
    endfunction
    //: {n*LN2_HI, RN(n*LN2_LO)}: the golden's binary32 products (hdc_golden.mul,
    //: canonical +0 at n = 0), indexed by n's low 8 bits.
    

    wire [DEPTH:0] vd;
    ot_hdc_vline_pooln #(.D(DEPTH)) u_v (.clk(clk), .rst_n(exp_reset[0]), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    // depth 1: clamp
    (* keep *) reg [31:0] xc;
    always @(posedge clk) begin
        if (!x[31] && x[30:0] > K_MAX[30:0]) xc <= K_MAX;
        else if (x[31] && x[30:0] > K_MINM[30:0]) xc <= {1'b1, K_MINM[30:0]};
        else xc <= x;
    end

    wire [31:0] t;
    wire [2:0] f;
    ot_hdc_qmul_lat_pooln #(LM) m_t (clk, exp_reset[1], vd[1], xc, K_LOG2E, t, f[0]);   // 1 + LM

    // n = rint-to-even(t), |t| < 127.  With E = field - 127, the integer part
    // is the significand shifted right by 23 - E (E in [-1, 6]); below E = -1,
    // |t| < 1/2 and n = 0.
    wire [23:0] tm = {1'b1, t[22:0]};
    wire [7:0]  te = t[30:23];
    wire [4:0]  tsh = 5'd23 - (te[4:0] - 5'd31);      // 23 - E, as te - 127 = te[4:0] - 31 (mod 32)
    wire [23:0] tip = tm >> tsh;
    wire [4:0]  trb = tsh - 5'd1;
    wire        thalf = tm[trb];
    wire        tstk = |(tm & ~({24{1'b1}} << trb));
    wire [7:0]  tmag = (te < 8'd126) ? 8'd0 : (tip[7:0] + {7'd0, thalf && (tstk || tip[0])});
    (* keep *) reg  [8:0]  nint;
    always @(posedge clk) nint <= t[31] ? -{1'b0, tmag} : {1'b0, tmag};

    wire [31:0] a_hi, a_lo;
    wire[63:0] nk_product;
    assign {a_hi,a_lo}=nk_product;
ot_pool_exp_table_0 u_table_0(clk,t,tmag,nk_product[0+:8]);
ot_pool_exp_table_1 u_table_1(clk,t,tmag,nk_product[8+:8]);
ot_pool_exp_table_2 u_table_2(clk,t,tmag,nk_product[16+:8]);
ot_pool_exp_table_3 u_table_3(clk,t,tmag,nk_product[24+:8]);
ot_pool_exp_table_4 u_table_4(clk,t,tmag,nk_product[32+:8]);
ot_pool_exp_table_5 u_table_5(clk,t,tmag,nk_product[40+:8]);
ot_pool_exp_table_6 u_table_6(clk,t,tmag,nk_product[48+:8]);
ot_pool_exp_table_7 u_table_7(clk,t,tmag,nk_product[56+:8]);

    wire [31:0] r1, r, xc_d, lo_d;
    ot_hdc_delay_pooln #(.W(32), .D(T_K - 1)) d_x (clk, exp_reset[2], xc, xc_d);
    ot_hdc_qadd_lat_pooln #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) a_r1 (clk, exp_reset[3], vd[T_K], xc_d, {~a_hi[31], a_hi[30:0]}, r1, f[1]);
    ot_hdc_delay_pooln #(.W(32), .D(LA)) d_lo (clk, exp_reset[4], a_lo, lo_d);
    ot_hdc_qadd_lat_pooln #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) a_r  (clk, exp_reset[5], vd[T_R1], r1, {~lo_d[31], lo_d[30:0]}, r, f[2]);

    // Horner: p = C0; six times p = p*r + C[k]; r travels in (LM+LA)-cycle hops.
    wire [31:0] rd [0:6];
    wire [31:0] pm [1:6];
    wire [31:0] pa [0:6];
    wire [12:1] hf;
    assign rd[0] = r;
    assign pa[0] = poly(0);
    genvar k;
    generate
        for (k = 1; k <= 6; k = k + 1) begin : g_h
            if (k < 6) begin : g_rd
                ot_hdc_delay_pooln #(.W(32), .D(LM + LA)) d_r (clk, exp_reset[6], rd[k-1], rd[k]);
            end
            ot_hdc_qmul_lat_pooln #(LM) u_m (clk, exp_reset[7], vd[T_R + (LM + LA)*(k-1)], pa[k-1], rd[k-1], pm[k], hf[2*k-1]);
            ot_hdc_qadd_lat_pooln #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) u_a (clk, exp_reset[8], vd[T_R + (LM + LA)*(k-1) + LM], pm[k], poly(k), pa[k], hf[2*k]);
        end
    endgenerate

    wire [8:0] nint_d;
    ot_hdc_delay_pooln #(.W(9), .D(T_P - T_N)) d_n (clk, exp_reset[9], nint, nint_d);
    // 2^n into the exponent field (a keep-prefix add in the serial-domain build, LM != 3)
    wire [31:0] y_n;
    wire        unused_cy;
    ot_hdc_kadd_pooln #(.W(32), .K((LM != 3 || LA != 3) ? 1 : 0)) u_yn (.a(pa[6]), .b({{14{nint_d[8]}}, nint_d, 23'd0}), .cin(1'b0),
                                                      .s(y_n), .cout(unused_cy));
    always @(posedge clk) y <= y_n;

    assign fault = |{f, hf};
endmodule

// 1/sqrt(v): seed 0x5f3759df - (bits >> 1), three steps y*(1.5 - half*(y*y)).
module ot_hdc_v41x_rsqrt_pooln #(
    parameter integer LM = 3,                   // multiplier latency (ot_hdc_qmul_lat_pooln)
    parameter integer LA = 3                    // add latency (ot_hdc_qadd_lat_pooln: 3, or 4 input cut)
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    output wire [31:0] y,
    output wire        vo,
    output wire        fault
);
    localparam integer IT = 3 * LM + LA;
    localparam integer DEPTH = 1 + 3 * IT;      // 37 (LM 3), 46 (LM 4)
    wire [DEPTH:0] vd;
    ot_hdc_vline_pooln #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    (* keep *) reg [31:0] y0;
    wire [31:0] y0_n;
    wire        unused_cy;
    ot_hdc_kadd_pooln #(.W(32), .K((LM != 3 || LA != 3) ? 1 : 0)) u_y0 (.a(32'h5F3759DF), .b(~{1'b0, x[31:1]}), .cin(1'b1), .s(y0_n),
                                                      .cout(unused_cy));
    always @(posedge clk) y0 <= y0_n;
    wire [31:0] half;
    wire [31:0] hd [0:2];
    wire [31:0] yi [0:3];
    wire [31:0] yy [0:2];
    wire [31:0] hm [0:2];
    wire [31:0] s [0:2];
    wire [31:0] yd [0:2];
    wire [12:0] f;
    ot_hdc_qmul_lat_pooln #(LM) m_half (clk, rst_n, v, x, 32'h3F000000, half, f[12]);   // LM
    ot_hdc_delay_pooln #(.W(32), .D(1)) d_h0 (clk, rst_n, half, hd[0]);       // 1 + LM
    assign yi[0] = y0;
    genvar k;
    generate
        for (k = 0; k < 3; k = k + 1) begin : g_nr
            if (k < 2) begin : g_h
                ot_hdc_delay_pooln #(.W(32), .D(IT)) d_h (clk, rst_n, hd[k], hd[k+1]);
            end
            ot_hdc_qmul_lat_pooln #(LM) m_yy (clk, rst_n, vd[1 + IT*k],             yi[k], yi[k], yy[k], f[4*k]);
            ot_hdc_qmul_lat_pooln #(LM) m_hm (clk, rst_n, vd[1 + IT*k + LM],        hd[k], yy[k], hm[k], f[4*k+1]);
            ot_hdc_qadd_lat_pooln #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) a_s  (clk, rst_n, vd[1 + IT*k + 2*LM],      32'h3FC00000, {~hm[k][31], hm[k][30:0]}, s[k], f[4*k+2]);
            ot_hdc_delay_pooln #(.W(32), .D(2*LM + LA)) d_y (clk, rst_n, yi[k], yd[k]);
            ot_hdc_qmul_lat_pooln #(LM) m_y  (clk, rst_n, vd[1 + IT*k + 2*LM + LA], yd[k], s[k], yi[k+1], f[4*k+3]);
        end
    endgenerate
    assign y = yi[3];
    assign fault = |f;
endmodule

// ---------------------------------------------------------------------------
// Correctly rounded binary32 DIVISION: II 1, fixed DEPTH 19.
//
// The function, the operand decode, the finish and the fault convention are
// those of rtl/hdc/v41/ot_hdc_fdiv.sv, transcribed unchanged:
//   y = RN_even(a / b), gradual underflow, every zero result +0; a nonfinite
//   operand, a zero divisor or an overflowing quotient fails closed
//   (fault, y = +0).
// What changes is the recurrence.  It forms the same 27 quotient bits and the
// same final remainder, but TWO bits per register stage.  A stage takes x = 4R
// (2 ma in the first stage), with R < mb the running remainder, so_pooln x < 4 mb.
// It forms x - mb, x - 2 mb and x - 3 mb in parallel, and the digit
// q = floor(x / mb) in [0, 3] is the largest with a non-negative difference.
// That is one subtract and a select, not two subtracts in series: the routed
// SFU lane measured two serial restoring steps at 907 MHz.  3 mb is formed
// once, in a stage after the decode.  The last stage forms one bit.  A
// correctly rounded quotient is unique, so_pooln the result is the same bit for bit.
// Stages: 1 decode, 1 (3 mb), 14 recurrence, 3 finish.
// ---------------------------------------------------------------------------
module ot_hdc_v41x_fdiv_pooln (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    (* keep *) output reg  [31:0] y,
    output wire        vo,
    (* keep *) output reg         fault
);
    localparam integer QB = 27;
    localparam integer NS = (QB + 1) / 2;      // 14
    localparam integer DEPTH = 2 + NS + 3;     // 19

    wire [DEPTH:0] vd;
    ot_hdc_vline_pooln #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    function automatic [33:0] norm;   // {sig[23:0], exponent[9:0] signed, unbiased of sig * 2^-23}
        input [7:0]  e;
        input [22:0] f;
        integer i;
        (* keep *) reg [4:0] p;
        begin
            if (e != 8'd0) norm = {1'b1, f, e - 10'sd127};
            else begin
                p = 5'd0;
                for (i = 0; i < 23; i = i + 1) if (f[i]) p = i[4:0];
                norm = {({1'b0, f} << (5'd23 - p)), $signed({5'd0, p}) - 10'sd149};
            end
        end
    endfunction
    wire [33:0] na = norm(a[30:23], a[22:0]);
    wire [33:0] nb = norm(b[30:23], b[22:0]);

    (* keep *) reg        d_sign, d_zero, d_bad;
    (* keep *) reg [23:0] d_ma, d_mb;
    (* keep *) reg signed [10:0] d_e;
    always @(posedge clk) begin
        d_sign <= a[31] ^ b[31];
        d_zero <= (a[30:0] == 31'd0);
        d_bad  <= (a[30:23] == 8'hFF) || (b[30:23] == 8'hFF) || (b[30:0] == 31'd0);
        d_ma   <= na[33:10];
        d_mb   <= nb[33:10];
        d_e    <= $signed({na[9], na[9:0]}) - $signed({nb[9], nb[9:0]});
    end

    // 3 mb, once
    (* keep *) reg        e_sign, e_zero, e_bad;
    (* keep *) reg [23:0] e_ma, e_mb;
    (* keep *) reg [25:0] e_mb3;
    (* keep *) reg signed [10:0] e_e;
    always @(posedge clk) begin
        e_sign <= d_sign; e_zero <= d_zero; e_bad <= d_bad; e_e <= d_e;
        e_ma <= d_ma; e_mb <= d_mb; e_mb3 <= {2'b0, d_mb} + {1'b0, d_mb, 1'b0};
    end

    (* keep *) reg [24:0]        r_rem  [0:NS-1];
    (* keep *) reg [QB-1:0]      r_q    [0:NS-1];
    (* keep *) reg [23:0]        r_mb   [0:NS-1];
    (* keep *) reg [25:0]        r_mb3  [0:NS-1];
    (* keep *) reg               r_sign [0:NS-1];
    (* keep *) reg               r_zero [0:NS-1];
    (* keep *) reg               r_bad  [0:NS-1];
    (* keep *) reg signed [10:0] r_e    [0:NS-1];

    genvar j;
    generate
        for (j = 0; j < NS; j = j + 1) begin : g_rec
            // quotient bits 2j and 2j+1 (bit 2^-k is restoring step k); stage NS-1 forms one bit
            localparam integer TWO = (2 * j + 1 < QB);
            wire [23:0]   mb  = (j == 0) ? e_mb : r_mb[j-1];
            wire [25:0]   mb3 = (j == 0) ? e_mb3 : r_mb3[j-1];
            wire [QB-1:0] qin = (j == 0) ? {QB{1'b0}} : r_q[j-1];
            wire [26:0]   x   = (j == 0) ? {2'b0, e_ma, 1'b0} :
                                TWO ? {r_rem[j-1][24:0], 2'b0} : {1'b0, r_rem[j-1][24:0], 1'b0};
            wire [27:0]   d1 = {1'b0, x} - {4'b0, mb};
            wire [27:0]   d2 = {1'b0, x} - {3'b0, mb, 1'b0};
            wire [27:0]   d3 = {1'b0, x} - {2'b0, mb3};
            wire [1:0]    q  = !d3[27] ? 2'd3 : !d2[27] ? 2'd2 : !d1[27] ? 2'd1 : 2'd0;
            wire [26:0]   r  = !d3[27] ? d3[26:0] : !d2[27] ? d2[26:0] : !d1[27] ? d1[26:0] : x;
            always @(posedge clk) begin
                r_rem[j]  <= r[24:0];
                r_q[j]    <= TWO ? {qin[QB-3:0], q} : {qin[QB-2:0], q[0]};
                r_mb[j]   <= mb;
                r_mb3[j]  <= mb3;
                r_sign[j] <= (j == 0) ? e_sign : r_sign[j-1];
                r_zero[j] <= (j == 0) ? e_zero : r_zero[j-1];
                r_bad[j]  <= (j == 0) ? e_bad  : r_bad[j-1];
                r_e[j]    <= (j == 0) ? e_e    : r_e[j-1];
            end
        end
    endgenerate

    // ---- finish 1: leading bit, significand, guard, sticky, biased exponent ----
    wire [QB-1:0] q = r_q[NS-1];
    (* keep *) reg        f1_sign, f1_zero, f1_bad, f1_g, f1_st;
    (* keep *) reg [23:0] f1_sig;
    (* keep *) reg signed [10:0] f1_be;
    always @(posedge clk) begin
        f1_sign <= r_sign[NS-1];
        f1_zero <= r_zero[NS-1];
        f1_bad  <= r_bad[NS-1];
        if (q[26]) begin
            f1_sig <= q[26:3]; f1_g <= q[2]; f1_st <= (|q[1:0]) || (|r_rem[NS-1]);
            f1_be  <= r_e[NS-1] + 11'sd127;
        end else begin
            f1_sig <= q[25:2]; f1_g <= q[1]; f1_st <= q[0] || (|r_rem[NS-1]);
            f1_be  <= r_e[NS-1] + 11'sd126;
        end
    end

    // ---- finish 2: denormalise a subnormal result -------------------------------
    wire        f1_sub = (f1_be < 11'sd1);
    wire [10:0] sh_full = 11'sd1 - f1_be;
    wire [4:0]  sh = (sh_full > 11'd25) ? 5'd25 : sh_full[4:0];
    wire [24:0] ext = {f1_sig, f1_g};
    wire [24:0] ext_sh = ext >> sh;
    wire [24:0] lost_mask = (25'd1 << sh) - 25'd1;
    (* keep *) reg        f2_sign, f2_zero, f2_bad, f2_ovf, f2_g, f2_st;
    (* keep *) reg [23:0] f2_sig;
    (* keep *) reg [7:0]  f2_field;
    always @(posedge clk) begin
        f2_sign <= f1_sign;
        f2_zero <= f1_zero;
        f2_bad  <= f1_bad;
        f2_ovf  <= (f1_be > 11'sd254);
        if (f1_sub) begin
            f2_sig <= ext_sh[24:1]; f2_g <= ext_sh[0];
            f2_st <= f1_st || (|(ext & lost_mask));
            f2_field <= 8'd0;
        end else begin
            f2_sig <= f1_sig; f2_g <= f1_g; f2_st <= f1_st;
            f2_field <= f1_be[7:0];
        end
    end

    // ---- finish 3: round to nearest even, encode ----------------------------------
    wire        rup = f2_g && (f2_st || f2_sig[0]);
    wire [30:0] code = {f2_field, f2_sig[22:0]} + {30'd0, rup};
    wire        ovf = f2_ovf || (code[30:23] == 8'hFF);
    always @(posedge clk) begin
        if (f2_bad || (ovf && !f2_zero)) begin y <= 32'd0; fault <= vd[DEPTH-1]; end
        else if (f2_zero || code == 31'd0) begin y <= 32'd0; fault <= 1'b0; end
        else begin y <= {f2_sign, code}; fault <= 1'b0; end
    end
endmodule

// ---------------------------------------------------------------------------
// softplus(x) and sqrt(softplus(x)): II 1, fixed DEPTH 162.  The operation order
// of rtl/hdc/v41/ot_hdc_softplus.sv (tools/hdc_golden_v41.softplus, .sqrt), on
// the fast units:
//     t = exp(-|x|)            49     ot_hdc_v41x_exp_pooln
//     u = t / (t + 2)          3 + 19 ot_hdc_qadd_pooln, ot_hdc_v41x_fdiv_pooln
//     u2 = u * u               3
//     p = 1/17; p = p*u2 + 1/(2i+1), i = 7 .. 0      8 x (3 + 3)
//     l = (u * p) * 2          3 + 3
//     sp = max(x, 0) + l       3
//     r = sqrt(sp)             31     ot_hdc_fsqrt
// The fault convention is ot_hdc_softplus's.
// ---------------------------------------------------------------------------
module ot_hdc_v41x_softplus_pooln #(
    parameter integer LM = 3,                   // multiplier latency (ot_hdc_qmul_lat_pooln)
    parameter integer LA = 3                    // add latency (ot_hdc_qadd_lat_pooln: 3, or 4 input cut)
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    output wire [31:0] sp,
    output wire [31:0] r,
    output wire        vo,
    output wire        fault
);
    localparam integer T_EXP  = 7 * LM + 8 * LA + 4;   // ot_hdc_v41x_exp_pooln DEPTH
    localparam integer T_DEN  = T_EXP + LA;
    localparam integer T_U    = T_DEN + 19;
    localparam integer T_U2   = T_U + LM;
    localparam integer T_P    = T_U2 + 8 * (LM + LA);
    localparam integer T_UP   = T_P + LM;
    localparam integer T_L    = T_UP + LM;
    localparam integer T_SP   = T_L + LA;
    localparam integer DEPTH  = T_SP + 31;       // 162 (LM 3), 180 (LM 4)
    localparam [32*9-1:0] C = {32'h3D70F0F1, 32'h3D888889, 32'h3D9D89D9, 32'h3DBA2E8C, 32'h3DE38E39,
                               32'h3E124925, 32'h3E4CCCCD, 32'h3EAAAAAB, 32'h3F800000};  // 1/17 .. 1/1
    function automatic [31:0] coef(input integer i);
        coef = C[32*(8-i) +: 32];
    endfunction

    wire [DEPTH:0] vd;
    ot_hdc_vline_pooln #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    wire [31:0] t, den, t_d, u, u2, lp, l;
    wire f_exp, f_den, f_div, f_u2, f_up, f_l, f_sp, f_sq;
    ot_hdc_v41x_exp_pooln #(.LM(LM), .LA(LA)) u_exp (.clk(clk), .rst_n(rst_n), .v(v), .x({1'b1, x[30:0]}), .y(t), .vo(), .fault(f_exp));
    ot_hdc_qadd_lat_pooln #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) a_den (clk, rst_n, vd[T_EXP], t, 32'h40000000, den, f_den);
    ot_hdc_delay_pooln #(.W(32), .D(LA)) d_t (clk, rst_n, t, t_d);
    ot_hdc_v41x_fdiv_pooln u_div (.clk(clk), .rst_n(rst_n), .v(vd[T_DEN]), .a(t_d), .b(den), .y(u), .vo(), .fault(f_div));
    ot_hdc_qmul_lat_pooln #(LM) m_u2 (clk, rst_n, vd[T_U], u, u, u2, f_u2);

    wire [31:0] u2d [0:7];
    wire [31:0] pm  [1:8];
    wire [31:0] pa  [0:8];
    wire [16:1] hf;
    assign u2d[0] = u2;
    assign pa[0] = coef(0);
    genvar k;
    generate
        for (k = 1; k <= 8; k = k + 1) begin : g_h
            if (k < 8) begin : g_d
                ot_hdc_delay_pooln #(.W(32), .D(LM + LA)) d_u2 (clk, rst_n, u2d[k-1], u2d[k]);
            end
            ot_hdc_qmul_lat_pooln #(LM) u_m (clk, rst_n, vd[T_U2 + (LM + LA)*(k-1)], pa[k-1], u2d[k-1], pm[k], hf[2*k-1]);
            ot_hdc_qadd_lat_pooln #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) u_a (clk, rst_n, vd[T_U2 + (LM + LA)*(k-1) + LM], pm[k], coef(k), pa[k], hf[2*k]);
        end
    endgenerate

    wire [31:0] u_d;
    ot_hdc_delay_pooln #(.W(32), .D(T_P - T_U)) d_u (clk, rst_n, u, u_d);
    ot_hdc_qmul_lat_pooln #(LM) m_up (clk, rst_n, vd[T_P], u_d, pa[8], lp, f_up);
    ot_hdc_qmul_lat_pooln #(LM) m_l  (clk, rst_n, vd[T_UP], lp, 32'h40000000, l, f_l);

    (* keep *) reg  [31:0] mx;
    wire [31:0] mx_d, spv;
    wire x_nan = (x[30:23] == 8'hFF) && (x[22:0] != 23'd0);
    always @(posedge clk) mx <= (x[31] && !x_nan) ? 32'd0 : x;
    ot_hdc_delay_pooln #(.W(32), .D(T_L - 1)) d_mx (clk, rst_n, mx, mx_d);
    ot_hdc_qadd_lat_pooln #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) a_sp (clk, rst_n, vd[T_L], mx_d, l, spv, f_sp);

    ot_hdc_fsqrt u_sq (.clk(clk), .rst_n(rst_n), .v(vd[T_SP]), .a(spv), .y(r), .vo(), .fault(f_sq));
    ot_hdc_delay_pooln #(.W(32), .D(DEPTH - T_SP)) d_sp (clk, rst_n, spv, sp);

    wire f_sp_d;
    ot_hdc_delay_pooln #(.W(1), .D(DEPTH - T_SP), .RESET(1)) d_fsp (clk, rst_n, f_sp, f_sp_d);
    assign fault = f_sp_d | f_sq | f_exp | f_den | f_div | f_u2 | (|hf) | f_up | f_l;
endmodule

// ---------------------------------------------------------------------------
// Insertion delay line: an item entering with depth choice k leaves exactly
// DEPTHS[k] cycles later (0 = a wire), all items through ONE exit.  It is a
// shift register toward the exit whose stage DEPTHS[k] also loads new items.
// Items keep their order only if every item leaves after the one before it;
// the controller guarantees that (ot_hdc_v41x_vec: the checkpoint rule).  A
// stage that is loaded while an item shifts into it raises `coll`.
// ---------------------------------------------------------------------------
module ot_hdc_v41x_ins_pooln #(
    parameter integer W = 32,
    parameter integer K = 2,                 // depth choices
    parameter [16*K-1:0] DEPTHS = {16'd3, 16'd0},   // choice k = DEPTHS[16k +: 16]
    parameter integer DMAX = 3,              // max over DEPTHS
    parameter integer RESET_DATA = 0
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         v,
    input  wire [K-1:0] sel,                 // one-hot depth choice
    input  wire [W-1:0] d,
    output wire         vo,
    output wire [W-1:0] q,
    output wire         coll,
    output wire         busy                 // an item is in the line
);
    function automatic has(input integer p, input [K-1:0] s);
        integer k;
        begin
            has = 1'b0;
            for (k = 0; k < K; k = k + 1) if (DEPTHS[16*k +: 16] == p && s[k]) has = 1'b1;
        end
    endfunction
    function automatic canbe(input integer p);
        integer k;
        begin
            canbe = 1'b0;
            for (k = 0; k < K; k = k + 1) if (DEPTHS[16*k +: 16] == p) canbe = 1'b1;
        end
    endfunction
    generate
        if (DMAX == 0) begin : g_wire
            assign vo = v; assign q = d; assign coll = 1'b0; assign busy = 1'b0;
        end else begin : g_line
            (* keep *) reg [W-1:0] r  [1:DMAX];
            (* keep *) reg         rv [1:DMAX];
            wire [DMAX+1:1] cl;
            assign cl[DMAX+1] = 1'b0;
            genvar p;
            for (p = 1; p <= DMAX; p = p + 1) begin : g_s
                wire [W-1:0] nx  = (p == DMAX) ? {W{1'b0}} : r[(p == DMAX) ? p : p + 1];
                wire         nxv = (p == DMAX) ? 1'b0 : rv[(p == DMAX) ? p : p + 1];
