`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// ot_dsrom_su_fdiv_f12_pooln: correctly rounded binary32 DIVISION for the 1.2 GHz domain (DS-ROM recovery lever
// su_softmax, default-off, new file).  The function, decode, finish and fault convention are those of
// ot_hdc_v41x_fdiv_pooln (rtl/hdc/v41x/ot_hdc_v41x_sfu.sv), bit for bit (rtl/test/tb_dsrom_su_fdiv_f12_eq.sv):
//   y = RN_even(a / b), gradual underflow, every zero result +0; a nonfinite operand, a zero divisor or an
//   overflowing quotient fails closed (fault, y = +0).
// Only the register boundaries move (the 19-deep unit screens -392 ps at 0.833 ns: its radix-4 step, its
// one-stage denormalise and its round-encode-select stage; the step subtract and the round increment are
// keep-prefix adders, ot_hdc_kadd_pooln / ot_hdc_kinc_pooln K 1):
//   2 decode (normalise | exponent difference) | 27 restoring steps, ONE quotient bit a stage (the same 27 bits and final remainder as the
//   radix-4 unit: floor(2x/mb) = 2 b_k + b_{k+1}) | F1 leading bit, sig, guard, sticky, biased exponent and the
//   subnormal shift | F2 denormalise | F3 round increment | F4 overflow test and select.   DEPTH 33, II 1.
// NR = 1 (MARGIN build, owner margin-first rule 2026-10-06; x6u40 r_mb -> r_rem +41 ps): NON-RESTORING steps.  The
//   partial remainder p_j = x_j - mb (x_j the restoring step's dividend) is kept signed; p_{j+1} = 2 p_j - mb when
//   p_j >= 0 else 2 p_j + mb, q_j = (p_j >= 0): the same 27 quotient bits, and no remainder select behind the
//   step's carry (the add/subtract choice is the previous step's registered sign).  One more stage (R) recovers the
//   restoring remainder's nonzero test carry-free: r = q ? p : p + mb, and p + mb == 0 (mod 2^27) iff
//   (p ^ mb) == ((p | mb) << 1).   DEPTH 34.
// ---------------------------------------------------------------------------
module ot_dsrom_su_fdiv_f12_pooln #(
    parameter integer NR = 0
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    (* keep *) output reg  [31:0] y,
    output wire        vo,
    (* keep *) output reg         fault
);
    localparam integer QB = 27;
    localparam integer SPL = (NR == 2) ? 1 : 0;                                 // NR 2: SAFE build, every step in two stages
    localparam integer DEPTH = 2 + QB + 4 + ((NR != 0) ? 1 : 0) + (SPL ? QB + 2 : 0);   // 33 (NR 0) / 34 (NR 1) / 63 (NR 2)

    wire [DEPTH:0] vd;
    ot_hdc_vline_pooln #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    function automatic [33:0] norm;   // {sig[23:0], exponent[9:0] signed, unbiased of sig * 2^-23}
        input [7:0]  e;
        input [22:0] f;
        integer i;
        (* keep *) reg [4:0] p;
        begin
            if (e != 8'd0) norm = {1'b1, f, e - 10'sd127};
            else begin
                p = 5'd0;
                for (i = 0; i < 23; i = i + 1) if (f[i]) p = i[4:0];
                norm = {({1'b0, f} << (5'd23 - p)), $signed({5'd0, p}) - 10'sd149};
            end
        end
    endfunction
    function automatic [4:0] lzp(input [22:0] f);   // position of the leading one of f (0 when f == 0)
        integer i; (* keep *) reg [4:0] p;
        begin p = 5'd0; for (i = 0; i < 23; i = i + 1) if (f[i]) p = i[4:0]; lzp = p; end
    endfunction
    function automatic [33:0] norm2(input [7:0] e, input [22:0] f, input [4:0] p);   // norm with the position given
        if (e != 8'd0) norm2 = {1'b1, f, e - 10'sd127};
        else norm2 = {({1'b0, f} << (5'd23 - p)), $signed({5'd0, p}) - 10'sd149};
    endfunction
    // NR 2: a decode stage ahead of the normalise registers the operands and the leading-one positions
    (* keep *) reg [31:0] z_a, z_b; (* keep *) reg [4:0] z_pa, z_pb;
    wire [31:0] da = SPL ? z_a : a;
    wire [31:0] db = SPL ? z_b : b;
    generate if (SPL) begin : g_z
        always @(posedge clk) begin z_a <= a; z_b <= b; z_pa <= lzp(a[22:0]); z_pb <= lzp(b[22:0]); end
    end else begin : g_nz
        always @* begin z_a = 32'd0; z_b = 32'd0; z_pa = 5'd0; z_pb = 5'd0; end
    end endgenerate
    // NR 2: the subnormal shift split in two stages: coarse (by 8 * sh[4:3]) here, fine (sh[2:0]) in the normalise stage
    (* keep *) reg [23:0] zz_ma, zz_mb; (* keep *) reg [2:0] zz_sa, zz_sb; (* keep *) reg [9:0] zz_ea, zz_eb; (* keep *) reg zz_sign, zz_zero, zz_bad;
    wire [4:0] sha = 5'd23 - z_pa, shb = 5'd23 - z_pb;
    generate if (SPL) begin : g_zz
        always @(posedge clk) begin
            zz_ma <= (da[30:23] != 8'd0) ? {1'b1, da[22:0]} : ({1'b0, da[22:0]} << {sha[4:3], 3'b000});
            zz_mb <= (db[30:23] != 8'd0) ? {1'b1, db[22:0]} : ({1'b0, db[22:0]} << {shb[4:3], 3'b000});
            zz_sa <= (da[30:23] != 8'd0) ? 3'd0 : sha[2:0];
            zz_sb <= (db[30:23] != 8'd0) ? 3'd0 : shb[2:0];
            zz_ea <= (da[30:23] != 8'd0) ? da[30:23] - 10'sd127 : $signed({5'd0, z_pa}) - 10'sd149;
            zz_eb <= (db[30:23] != 8'd0) ? db[30:23] - 10'sd127 : $signed({5'd0, z_pb}) - 10'sd149;
            zz_sign <= da[31] ^ db[31];
            zz_zero <= (da[30:0] == 31'd0);
            zz_bad  <= (da[30:23] == 8'hFF) || (db[30:23] == 8'hFF) || (db[30:0] == 31'd0);
        end
    end else begin : g_nzz
        always @* begin zz_ma = 24'd0; zz_mb = 24'd0; zz_sa = 3'd0; zz_sb = 3'd0; zz_ea = 10'd0; zz_eb = 10'd0; zz_sign = 1'b0; zz_zero = 1'b0; zz_bad = 1'b0; end
    end endgenerate
    wire [33:0] na = SPL ? {(zz_ma << zz_sa), zz_ea} : norm(a[30:23], a[22:0]);
    wire [33:0] nb = SPL ? {(zz_mb << zz_sb), zz_eb} : norm(b[30:23], b[22:0]);

    // decode in two stages: normalise both operands (subnormal leading-one count and shift) | exponent difference
    (* keep *) reg        n_sign, n_zero, n_bad;
    (* keep *) reg [33:0] n_a, n_b;
    always @(posedge clk) begin
        n_sign <= SPL ? zz_sign : (a[31] ^ b[31]);
        n_zero <= SPL ? zz_zero : (a[30:0] == 31'd0);
        n_bad  <= SPL ? zz_bad : ((a[30:23] == 8'hFF) || (b[30:23] == 8'hFF) || (b[30:0] == 31'd0));
        n_a    <= na;
        n_b    <= nb;
    end
    (* keep *) reg        d_sign, d_zero, d_bad;
    (* keep *) reg [23:0] d_ma, d_mb;
    (* keep *) reg signed [10:0] d_e;
    always @(posedge clk) begin
        d_sign <= n_sign;
        d_zero <= n_zero;
        d_bad  <= n_bad;
        d_ma   <= n_a[33:10];
        d_mb   <= n_b[33:10];
        d_e    <= $signed({n_a[9], n_a[9:0]}) - $signed({n_b[9], n_b[9:0]});
    end

    (* keep *) reg [24:0]        r_rem  [0:QB-1];
    (* keep *) reg [QB-1:0]      r_q    [0:QB-1];
    (* keep *) reg [23:0]        r_mb   [0:QB-1];
    (* keep *) reg               r_sign [0:QB-1];
    (* keep *) reg               r_zero [0:QB-1];
    (* keep *) reg               r_bad  [0:QB-1];
    (* keep *) reg signed [10:0] r_e    [0:QB-1];
    wire [QB-1:0]     fq;                                       // the step array's result, F1's inputs
    wire              fsign, fzero, fbad, fnz;
    wire signed [10:0] fe;
    genvar j;
    generate if (SPL) begin : g_sp
        (* keep *) reg [26:0] p_rem [0:QB-1];
        for (j = 0; j < QB; j = j + 1) begin : g_rec
            wire [23:0]   mb  = (j == 0) ? d_mb : r_mb[j-1];
            wire [QB-1:0] qin = (j == 0) ? {QB{1'b0}} : r_q[j-1];
            wire          sub = (j == 0) ? 1'b1 : r_q[j-1][0];
            wire [26:0]   x   = (j == 0) ? {3'b0, d_ma} : {p_rem[j-1][25:0], 1'b0};
            wire [26:0]   opb = sub ? ~{3'b0, mb} : {3'b0, mb};
            wire [12:0]   lo_s; wire lo_c;                                          // stage A: low half (keep-prefix: ABC cannot re-ripple it)
            ot_hdc_kadd_pooln #(.W(13), .K(1)) u_lo (.a(x[12:0]), .b(opb[12:0]), .cin(sub), .s(lo_s), .cout(lo_c));
            wire [13:0]   lo  = {lo_c, lo_s};
            wire [13:0]   h0, h1; wire h0_c, h1_c;                                  // upper half, both carries
            ot_hdc_kadd_pooln #(.W(14), .K(1)) u_h0 (.a(x[26:13]), .b(opb[26:13]), .cin(1'b0), .s(h0), .cout(h0_c));
            ot_hdc_kadd_pooln #(.W(14), .K(1)) u_h1 (.a(x[26:13]), .b(opb[26:13]), .cin(1'b1), .s(h1), .cout(h1_c));
            (* keep *) reg  [12:0] a_lo; (* keep *) reg a_cl; (* keep *) reg [13:0] a_h0, a_h1;
            (* keep *) reg  [23:0] a_mb; (* keep *) reg [QB-1:0] a_q; (* keep *) reg a_sign, a_zero, a_bad; (* keep *) reg signed [10:0] a_e;
            always @(posedge clk) begin
                a_lo <= lo[12:0]; a_cl <= lo[13]; a_h0 <= h0; a_h1 <= h1;
                a_mb <= mb; a_q <= qin;
                a_sign <= (j == 0) ? d_sign : r_sign[j-1];
                a_zero <= (j == 0) ? d_zero : r_zero[j-1];
                a_bad  <= (j == 0) ? d_bad  : r_bad[j-1];
                a_e    <= (j == 0) ? d_e    : r_e[j-1];
            end
            wire [26:0] p = {a_cl ? a_h1 : a_h0, a_lo};                             // stage B: select by the low carry
            always @(posedge clk) begin
                p_rem[j]  <= p;
                r_q[j]    <= {a_q[QB-2:0], !p[26]};
                r_mb[j]   <= a_mb;
                r_sign[j] <= a_sign; r_zero[j] <= a_zero; r_bad[j] <= a_bad; r_e[j] <= a_e;
            end
        end
        wire [26:0] pl = p_rem[QB-1];
        wire [26:0] ml = {3'b0, r_mb[QB-1]};
        wire        pz = (pl == 27'd0);
        wire        pmz = ((pl ^ ml) == {pl[25:0] | ml[25:0], 1'b0});
        (* keep *) reg [QB-1:0]      x_q;
        (* keep *) reg               x_sign, x_zero, x_bad, x_nz;
        (* keep *) reg signed [10:0] x_e;
        always @(posedge clk) begin
            x_q <= r_q[QB-1]; x_sign <= r_sign[QB-1]; x_zero <= r_zero[QB-1]; x_bad <= r_bad[QB-1];
            x_e <= r_e[QB-1];
            x_nz <= r_q[QB-1][0] ? !pz : !pmz;
        end
        assign fq = x_q; assign fsign = x_sign; assign fzero = x_zero; assign fbad = x_bad; assign fe = x_e;
        assign fnz = x_nz;
    end else if (NR) begin : g_nr
        (* keep *) reg [26:0] p_rem [0:QB-1];                              // signed partial remainder
        for (j = 0; j < QB; j = j + 1) begin : g_rec
            wire [23:0]   mb  = (j == 0) ? d_mb : r_mb[j-1];
            wire [QB-1:0] qin = (j == 0) ? {QB{1'b0}} : r_q[j-1];
            wire          sub = (j == 0) ? 1'b1 : r_q[j-1][0];  // previous p >= 0: subtract mb, else add it
            wire [26:0]   x   = (j == 0) ? {3'b0, d_ma} : {p_rem[j-1][25:0], 1'b0};
            wire [26:0]   p;
            wire          unused_c;
            ot_hdc_kadd_pooln #(.W(27), .K(1)) u_as (.a(x), .b(sub ? ~{3'b0, mb} : {3'b0, mb}), .cin(sub), .s(p),
                                               .cout(unused_c));
            always @(posedge clk) begin
                p_rem[j]  <= p;
                r_q[j]    <= {qin[QB-2:0], !p[26]};
                r_mb[j]   <= mb;
                r_sign[j] <= (j == 0) ? d_sign : r_sign[j-1];
                r_zero[j] <= (j == 0) ? d_zero : r_zero[j-1];
                r_bad[j]  <= (j == 0) ? d_bad  : r_bad[j-1];
                r_e[j]    <= (j == 0) ? d_e    : r_e[j-1];
            end
        end
        // R: the restoring remainder's nonzero test; the rest of the step state moves one stage
        wire [26:0] pl = p_rem[QB-1];
        wire [26:0] ml = {3'b0, r_mb[QB-1]};
        wire        pz = (pl == 27'd0);
        wire        pmz = ((pl ^ ml) == {pl[25:0] | ml[25:0], 1'b0});
        (* keep *) reg [QB-1:0]      x_q;
        (* keep *) reg               x_sign, x_zero, x_bad, x_nz;
        (* keep *) reg signed [10:0] x_e;
        always @(posedge clk) begin
            x_q <= r_q[QB-1]; x_sign <= r_sign[QB-1]; x_zero <= r_zero[QB-1]; x_bad <= r_bad[QB-1];
            x_e <= r_e[QB-1];
            x_nz <= r_q[QB-1][0] ? !pz : !pmz;
        end
        assign fq = x_q; assign fsign = x_sign; assign fzero = x_zero; assign fbad = x_bad; assign fe = x_e;
        assign fnz = x_nz;
    end else begin : g_rs
        for (j = 0; j < QB; j = j + 1) begin : g_rec
            wire [23:0]   mb  = (j == 0) ? d_mb : r_mb[j-1];
            wire [QB-1:0] qin = (j == 0) ? {QB{1'b0}} : r_q[j-1];
            wire [25:0]   x   = (j == 0) ? {2'b0, d_ma} : {r_rem[j-1][24:0], 1'b0};
            wire [26:0]   d1;                                   // x - mb (keep-prefix: ABC cannot re-ripple it)
            wire          bq;                                   // x >= mb: the carry out of x + ~mb + 1
            ot_hdc_kadd_pooln #(.W(27), .K(1)) u_sub (.a({1'b0, x}), .b(~{3'b0, mb}), .cin(1'b1), .s(d1), .cout(bq));
            always @(posedge clk) begin
                r_rem[j]  <= bq ? d1[24:0] : x[24:0];
                r_q[j]    <= {qin[QB-2:0], bq};
                r_mb[j]   <= mb;
                r_sign[j] <= (j == 0) ? d_sign : r_sign[j-1];
                r_zero[j] <= (j == 0) ? d_zero : r_zero[j-1];
                r_bad[j]  <= (j == 0) ? d_bad  : r_bad[j-1];
                r_e[j]    <= (j == 0) ? d_e    : r_e[j-1];
            end
        end
        assign fq = r_q[QB-1]; assign fsign = r_sign[QB-1]; assign fzero = r_zero[QB-1]; assign fbad = r_bad[QB-1];
        assign fe = r_e[QB-1]; assign fnz = |r_rem[QB-1];
    end endgenerate

    // ---- F1: leading bit, significand, guard, sticky, biased exponent, subnormal shift ----
    wire [QB-1:0] q = fq;
    wire signed [10:0] be1 = fe + (q[26] ? 11'sd127 : 11'sd126);
    (* keep *) reg        f1_sign, f1_zero, f1_bad, f1_g, f1_st, f1_sub, f1_ovf;
    (* keep *) reg [23:0] f1_sig;
    (* keep *) reg [7:0]  f1_field;
    (* keep *) reg [4:0]  f1_sh;
    wire [10:0] sh_full = 11'sd1 - be1;
    always @(posedge clk) begin
        f1_sign <= fsign;
        f1_zero <= fzero;
        f1_bad  <= fbad;
        if (q[26]) begin
            f1_sig <= q[26:3]; f1_g <= q[2]; f1_st <= (|q[1:0]) || fnz;
        end else begin
            f1_sig <= q[25:2]; f1_g <= q[1]; f1_st <= q[0] || fnz;
        end
        f1_sub   <= (be1 < 11'sd1);
        f1_ovf   <= (be1 > 11'sd254);
        f1_field <= be1[7:0];
        f1_sh    <= (sh_full > 11'd25) ? 5'd25 : sh_full[4:0];
    end

    // ---- F2: denormalise a subnormal result ----
    wire [24:0] ext = {f1_sig, f1_g};
    wire [24:0] ext_sh = ext >> f1_sh;
    wire [24:0] lost_mask = (25'd1 << f1_sh) - 25'd1;
    (* keep *) reg        f2_sign, f2_zero, f2_bad, f2_ovf, f2_g, f2_st;
    (* keep *) reg [23:0] f2_sig;
    (* keep *) reg [7:0]  f2_field;
    always @(posedge clk) begin
        f2_sign <= f1_sign;
        f2_zero <= f1_zero;
        f2_bad  <= f1_bad;
        f2_ovf  <= f1_ovf;
        if (f1_sub) begin
            f2_sig <= ext_sh[24:1]; f2_g <= ext_sh[0];
            f2_st <= f1_st || (|(ext & lost_mask));
            f2_field <= 8'd0;
        end else begin
            f2_sig <= f1_sig; f2_g <= f1_g; f2_st <= f1_st;
            f2_field <= f1_field;
        end
    end

    // ---- F3: round to nearest even ----
    (* keep *) reg        f3_sign, f3_zero, f3_bad, f3_ovf;
    (* keep *) reg [30:0] f3_code;
    wire [30:0] code_inc;
    ot_hdc_kinc_pooln #(.W(31), .K(1)) u_rnd (.a({f2_field, f2_sig[22:0]}), .inc(f2_g && (f2_st || f2_sig[0])), .y(code_inc));
    always @(posedge clk) begin
        f3_sign <= f2_sign; f3_zero <= f2_zero; f3_bad <= f2_bad; f3_ovf <= f2_ovf;
        f3_code <= code_inc;
    end

    // ---- F4: overflow and select ----
    wire ovf = f3_ovf || (f3_code[30:23] == 8'hFF);
    always @(posedge clk) begin
        if (f3_bad || (ovf && !f3_zero)) begin y <= 32'd0; fault <= vd[DEPTH-1]; end
        else if (f3_zero || f3_code == 31'd0) begin y <= 32'd0; fault <= 1'b0; end
        else begin y <= {f3_sign, f3_code}; fault <= 1'b0; end
    end
endmodule

// SAFE tile (owner 2026-10-06): the divider as a hardened leaf with both operands registered at the boundary (+1 cycle).
module ot_dsrom_su_fdiv_tile_pooln #(parameter integer NR = 0) (   // NR 0 / 1 / 2 as ot_dsrom_su_fdiv_f12_pooln
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    output wire [31:0] y,
    output wire        vo,
    output wire        fault
);
    (* keep *) reg [31:0] ar, br; (* keep *) reg vr;
    always @(posedge clk) begin ar <= a; br <= b; end
    always @(posedge clk or negedge rst_n) if (!rst_n) vr <= 1'b0; else vr <= v;
    ot_dsrom_su_fdiv_f12_pooln #(.NR(NR)) u (.clk(clk), .rst_n(rst_n), .v(vr), .a(ar), .b(br), .y(y), .vo(vo), .fault(fault));
endmodule

// SAFE half-rate backstop (owner 2026-10-07): two unchanged dividers on clock-gated half-rate domains (even / odd cycles),
// II 1 outside, multicycle-2 SDC on u_a.* / u_b.*.  Latency a,b -> y: 2 * DEPTH + 1 (DEPTH 33 NR 0, 34 NR 1).
module ot_dsrom_su_fdiv_hr_pooln #(parameter integer NR = 0) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] a,
    input  wire [31:0] b,
    (* keep *) output reg  [31:0] y,
    output wire        vo,
    output wire        fault
);
    localparam integer DEPTH = 2 + 27 + 4 + ((NR != 0) ? 1 : 0);
    (* keep *) reg ph; (* keep *) reg [31:0] ar, br; (* keep *) reg vr;
    always @(posedge clk or negedge rst_n) if (!rst_n) begin ph <= 1'b0; vr <= 1'b0; end else begin ph <= ~ph; vr <= v; end
    always @(posedge clk) begin ar <= a; br <= b; end
    wire gclk_a, gclk_b;
    ot_hdc_cg u_cga (.clk(clk), .en(!ph | !rst_n), .gclk(gclk_a));
    ot_hdc_cg u_cgb (.clk(clk), .en(ph | !rst_n), .gclk(gclk_b));
    wire [31:0] ya, yb; wire fa, fb;
    ot_dsrom_su_fdiv_f12_pooln #(.NR(NR)) u_a (.clk(gclk_a), .rst_n(rst_n), .v(vr & ~ph), .a(ar), .b(br), .y(ya), .vo(), .fault(fa));
    ot_dsrom_su_fdiv_f12_pooln #(.NR(NR)) u_b (.clk(gclk_b), .rst_n(rst_n), .v(vr & ph), .a(ar), .b(br), .y(yb), .vo(), .fault(fb));
    always @(posedge clk) y <= ph ? ya : yb;      // A updates at the end of even cycles (ph 0), visible while ph = 1
    wire [2*DEPTH+1:0] vd;
    ot_hdc_vline_pooln #(.D(2 * DEPTH + 1)) u_vl (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[2*DEPTH+1];
    assign fault = fa | fb;
endmodule

// Original source: rtl/hdc/v41x/ot_dsrom_su_norm.sv
`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// DS-ROM recovery, SU chains (lever su_norm): ONE fused 1.2 GHz pipeline for an RMSNorm chain of the V4.1 decode
// layer, with no vector-memory round trip between its steps:
//
//   HC = 1  hc_pre:  x_j = bf16(((h0_j*p0 + h1_j*p1) + h2_j*p2) + h3_j*p3)   (tools/hdc_golden_v41 Model.hc_pre:
//                    to_bf16(seqsum([mul(pre[k], h[k])])))
//   HC = 0  x_j is the input itself (q latent, kv latent: already BF16 values)
//   then    ss   = csum(x_j * x_j)                (R-ARITH chunk8: chunks of 8 summed sequentially, chunk sums by a
//                                                  pairwise tree padded with +0 to a power of two)
//           r    = rsqrt(ss / D + eps)            (golden div RNE: D = 5 * 2^k or 2^k, ot_dsrom_divc; add; rsqrt =
//                                                  3 Newton steps from 0x5F3759DF)
//           y_j  = bf16(w_j * (x_j * r))          (rmsnorm_bf16)
//   RD > 0  y's last RD elements rotated as adjacent pairs (rope_tail, forward): re = a*c + (-(b*s)),
//           im = b*c + a*s, BF16
//   QUANT   FP8 act-quant of each 32-element block (ot_dsrom_aq12: ot_hdc_actquant's FP8 function re-staged for
//           1.2 GHz, latency 18: codes, exponent, dequantised BF16)
//
// The golden's order is kept exactly: the four mix products are independent (one multiply level), the three adds
// are sequential; the square, the 7-add chunk chain and the tree are ot_hdc_v41x_vec_red's contract; the vector
// sums of a D > N row combine by the golden tree's top levels over NV = ceil(D/N) vectors padded to a power of two,
// where a node whose right subtree is all padding PASSES its left value (x + (+0) = x exactly for x >= +0: a sum of
// squares is never -0, every zero result being +0), so_pooln a padded level costs nothing.
//
// Layout: lane l of vector v holds element v*N + l (N a power of two >= 8, so_pooln every chunk is 8 lanes of one vector
// and a vector's N/8 chunk sums form an aligned subtree of the golden tree).  Lanes past D carry +0.
//
// Timing (1.2 GHz units: ot_hdc_qmul_lat_pooln LM 5 / ot_hdc_qadd_lat_pooln LA 4 through rtl/hdc/ot_hdc_fastfp_lat_f12.sv):
//   mix LM + 3 LA + 1 (HC), square LM, chain 7 LA, tree log2(N/8) LA, vector levels LA per real add,
//   RW result-wire stages, divide by D 8 (ot_dsrom_divc), + eps LA, rsqrt 1 + 3(3 LM + LA) (ot_dsrom_rsqrt_pooln = ot_hdc_v41x_rsqrt_pooln with ot_dsrom_qadd_pooln),
//   BW broadcast-wire stages back to the lanes, scale 2 LM + 1, RoPE (LM+1) + (LA+1) + 1, act-quant 18.
// The x values wait in the lanes (NV words a lane) between the mix and the scale: nothing is written back.
// ---------------------------------------------------------------------------
module ot_dsrom_su_norm_pooln #(
    parameter integer N = 1024,         // lanes (a power of two >= 8)
    parameter integer D = 5120,         // row length (a multiple of 8)
    parameter integer HC = 1,           // 1: four-copy hc_pre mix in front; 0: plain input
    parameter integer RD = 0,           // RoPE tail length (0: none; the tail lies in the last vector)
    parameter integer QUANT = 1,        // FP8 act-quant of the output (N a multiple of 32)
    parameter integer RXS = 0,          // 1: one more register stage on the RoPE operands (cycles for margin)
    parameter integer FREG = 0,         // 1: the sticky fault's reduction registered (per-lane, then per-group, +2 cycles on
                                        //    the fault flag only): the rope adder's err -> flt OR spanned the block
    parameter integer SXC = 0,          // 1: the scale multipliers (x*r, w*(x*r)) on the operand-cut multiplier (LM+1):
                                        //    their first stage is fed from another unit (xo, the broadcast rh, u_xr)
    parameter integer MEMSPLIT = 0,     // 1: the per-lane x wait line / gain ROM are keep_hierarchy modules (host synthesis of wide
                                        //    engines); 0: the original in-lane arrays (existing views byte-identical)
    parameter integer MEM = 0,          // 1: the x wait line and the gain ROM as two shared-address SRAMs (NV rows x N*32 bits,
                                        //    N/8 ASAP7 ot_sram_1r1w_128x256_m1_r2c2 macros each) instead of N per-lane flop
                                        //    arrays: every lane uses the same global index, so_pooln the N arrays are one wide
                                        //    memory.  The macro read is issued one cycle earlier and its output registered
                                        //    at the old xo / wo flops, so_pooln the operand timing is cycle-identical to MEM=0.
                                        //    Needs NV <= 128, N a multiple of 8, LM + SXC >= 2.
    parameter integer GH = 0,           // 1 (RD = 0 only; hgi-1010 HC engine): cos_t[0] = "the gain ROM is loaded": the scale
                                        //    sequencer starts when the rstd has landed AND cos_t[0], so_pooln the gain may stream in
                                        //    while the row's sum is formed.  0: unchanged (cos_t unused at RD = 0)
    parameter integer RW = 9,           // result wire stages (lane tree -> scalar tail)
    parameter integer BW = 9,           // broadcast wire stages (scalar tail -> lanes)
    parameter integer LM = 5,
    parameter integer LA = 4            // add latency: 4 f12_l4, 5 l5x (input cut), 6 l6 (input cut + compare cut;
                                        //    ot_dsrom_fp32_add_f12_l6_pooln) -- cycles for routed margin
) (
    input  wire                     clk,
    input  wire                     rst_n,
    input  wire                     go,             // a new row starts (clears the vector-level tree)
    input  wire                     in_v,           // one input vector a cycle, v = 0 .. NV-1 in order
    input  wire [(HC ? 4 : 1)*N*32-1:0] in_x,       // HC: copy k of lane l at [(k*N + l)*32 +: 32]
    input  wire [127:0]             pre,            // HC mix weights p0..p3
    input  wire [31:0]              n_f,            // binary32 D (the mean's divisor)
    input  wire [31:0]              eps,
    input  wire                     wl_v,           // gain ROM load: vector wl_i of w
    input  wire [7:0]               wl_i,
    input  wire [N*32-1:0]          wl_d,
    input  wire [(RD ? RD/2 : 1)*32-1:0] cos_t,     // RoPE table (constants of the position)
    input  wire [(RD ? RD/2 : 1)*32-1:0] sin_t,
    output wire                     y_v,            // normalised vector (BF16 values as binary32)
    output wire [7:0]               y_i,
    output wire [N*32-1:0]          y,
    output wire                     r_v,            // the scalar rstd (observability)
    output wire [31:0]              r,
    output wire                     q_v,            // act-quant (QUANT): one vector of blocks a cycle
    output wire [7:0]               q_i,
    output wire [(QUANT ? N/32 : 1)*256-1:0] q_codes,
    output wire [(QUANT ? N/32 : 1)*10-1:0]  q_e,
    output wire [(QUANT ? N/32 : 1)*512-1:0] q_y,
    output wire                     ro_v,           // RoPE output (RD), full vector
    output wire [N*32-1:0]          ro,
    output wire                     fault
);
    localparam integer NV  = (D + N - 1) / N;
    localparam integer NVP = (NV <= 1) ? 1 : (1 << $clog2(NV));
    localparam integer NC  = N / 8;
    localparam integer LT  = $clog2(NC);
    localparam integer DM  = HC ? (LM + 3 * LA + 1) : 0;    // mix depth
    localparam integer DS  = LM + 7 * LA + LT * LA;         // square + chain + tree
    localparam integer DR  = 1 + 3 * (3 * LM + LA);         // ot_hdc_v41x_rsqrt_pooln DEPTH
    localparam integer KS  = 1;
    localparam integer LB  = D - (NV - 1) * N;            // length of the last vector
    localparam integer LAV = (LA >= 5) ? LA : LA + 1;     // vector-level adds: an input-cut adder (l5x / l6)
    function automatic integer tz(input integer x);
        integer t;
        begin
            t = 0;
            while (t < 31 && ((x >> t) & 1) == 0) t = t + 1;
            tz = t;
        end
    endfunction
    localparam integer DK  = tz(D);                         // D = DF * 2^DK
    localparam integer DF  = D >> DK;

    function automatic [31:0] bf16(input [31:0] x);         // RNE to BF16 (tools/hdc_golden.to_bf16)
        (* keep *) reg [32:0] s;
        begin
            s = {1'b0, x} + 33'h7FFF + {32'd0, x[16]};
            bf16 = {s[31:16], 16'd0};
        end
    endfunction

    // ---------------------------------------------------------------- input vector index
    (* keep *) reg  [7:0] in_i;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) in_i <= 8'd0;
        else if (go) in_i <= 8'd0;
        else if (in_v) in_i <= in_i + 8'd1;

    // ---------------------------------------------------------------- control lines
    localparam integer LMS = LM + SXC;                      // scale multiplier latency
    localparam integer DY = 2 * LMS + 1;                    // scale depth
    wire [(DM > 0 ? DM : 1):0] vm_w;
    ot_hdc_vline_pooln #(.D(DM > 0 ? DM : 1)) u_vm (.clk(clk), .rst_n(rst_n), .v(in_v), .vd(vm_w));
    wire [DM:0] vm = vm_w[DM:0];
    wire [7:0] xi;
    ot_hdc_delay_pooln #(.W(8), .D(DM)) u_xi (.clk(clk), .rst_n(rst_n), .d(in_i), .q(xi));
    (* keep *) reg in_last;                        // in_i == NV - 1, registered with in_i
    always @(posedge clk or negedge rst_n)
        if (!rst_n) in_last <= (NV == 1);
        else if (go) in_last <= (NV == 1);
        else if (in_v) in_last <= (in_i + 8'd1 == NV - 1);
    wire x_last;
    ot_hdc_delay_pooln #(.W(1), .D(DM)) u_xl (.clk(clk), .rst_n(rst_n), .d(in_last), .q(x_last));
    wire x_v = vm[DM];
    wire [DS:0] vs;
    ot_hdc_vline_pooln #(.D(DS)) u_vs (.clk(clk), .rst_n(rst_n), .v(x_v), .vd(vs));
    wire [7:0] si;
    ot_hdc_delay_pooln #(.W(8), .D(DS)) u_si (.clk(clk), .rst_n(rst_n), .d(xi), .q(si));
    // scale sequencer: vector 0 goes in the cycle the broadcast rstd lands, 1 .. NV-1 after it.  The broadcast
    // wire's last stage is a hold register (rh), and each lane's x operand is read from its buffer a cycle ahead
    // (xo), so_pooln the multiplier sees registers only.
    wire        rb_v;
    (* keep *) reg  [31:0] rh;
    wire [32:0] rbw;                    // BW - 1 pipeline stages, then the hold register rh (the BW-th stage)
    wire        rbs;                    // the scale start (= rbw[32]; GH = 1: held until cos_t[0])
    (* keep *) reg         sc_run;
    (* keep *) reg  [7:0]  sc_i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin sc_run <= 1'b0; sc_i <= 8'd0; end
        else if (rb_v) begin sc_run <= (NV > 1); sc_i <= 8'd1; end
        else if (sc_run) begin
            if (sc_i == NV - 1) sc_run <= 1'b0;
            sc_i <= sc_i + 8'd1;
        end
    end
    wire        sc_go = rb_v || sc_run;
    wire [7:0]  sc_x  = rb_v ? 8'd0 : sc_i;
    wire [7:0]  sc_nx = rb_v ? 8'd1 : sc_run ? sc_i + 8'd1 : 8'd0;   // the index used in the next cycle
    // MEM=1: the index sc_nx will have in the NEXT cycle (the macro read is issued a cycle ahead of the xo register);
    // rb_v of the next cycle is rbw[32] now
    wire        sc_run_n = rb_v ? (NV > 1) : (sc_run && sc_i != NV - 1);
    wire [7:0]  sc_i_n   = rb_v ? 8'd1 : sc_run ? sc_i + 8'd1 : sc_i;
`ifdef OT_SUN_MEM_MUT_LATE
    wire [7:0]  sc_nn    = sc_nx;                                  // NEGATIVE CONTROL: read not issued ahead
`else
    wire [7:0]  sc_nn    = rbs ? 8'd1 : sc_run_n ? sc_i_n + 8'd1 : 8'd0;
`endif
    wire [DY:0] vy;
    ot_hdc_vline_pooln #(.D(DY)) u_vy (.clk(clk), .rst_n(rst_n), .v(sc_go), .vd(vy));
    wire [7:0] yi_m, yi_o;
    ot_hdc_delay_pooln #(.W(8), .D(LMS)) u_yim (.clk(clk), .rst_n(rst_n), .d(sc_nx), .q(yi_m));   // gain read a cycle ahead (wo)
    wire [7:0] yi_mm;                   // MEM=1: the gain read issued a cycle ahead of wo
    ot_hdc_delay_pooln #(.W(8), .D(LMS > 1 ? LMS - 1 : 1)) u_yimm (.clk(clk), .rst_n(rst_n), .d(sc_nx), .q(yi_mm));
    ot_hdc_delay_pooln #(.W(8), .D(DY)) u_yio (.clk(clk), .rst_n(rst_n), .d(sc_x), .q(yi_o));

    wire [N-1:0]    lf;                 // lane faults
    wire [N*32-1:0] sq;                 // squares (lanes past D: +0)
    wire [NC*32-1:0] cs;                // chunk sums
    wire [NC-1:0]   cf;
    wire [N*32-1:0] yb;
    wire [N*32-1:0] ybr;                // the RoPE's copy of yb

    genvar l, c, k, n;
    wire [N*32-1:0] xl_all;             // MEM=1: the lanes' x, one wide write word
    wire [N*32-1:0] xmq, wmq;           // MEM=1: the macros' read words (registered in the lanes as xo / wo)
    generate
        if (MEM) begin : g_mem
            // x wait line: written at xi on x_v (the lanes' mix outputs), read at sc_nn; gain ROM: written at wl_i on
            // wl_v, read at yi_mm.  Read-before-write on a same-address collision, as the flop arrays.
`ifdef OT_SUN_MEM_MUT_ADDR
            wire [6:0] xwa = xi[6:0] + 7'd1;                       // NEGATIVE CONTROL: write address off by one
`else
            wire [6:0] xwa = xi[6:0];
`endif
            for (c = 0; c < N / 8; c = c + 1) begin : g_m
                ot_sram_1r1w_128x256_m1_r2c2 u_x (.clk(clk), .r_ce_in(1'b1), .r_addr_in(sc_nn[6:0]),
                    .rd_out(xmq[c * 256 +: 256]), .w_ce_in(x_v), .w_addr_in(xwa), .wd_in(xl_all[c * 256 +: 256]),
                    .w_mask_in({256{1'b1}}), .rr_en(2'b00), .rr_addr(14'd0), .cr_en(2'b00), .cr_sel(16'd0));
                ot_sram_1r1w_128x256_m1_r2c2 u_w (.clk(clk), .r_ce_in(1'b1), .r_addr_in(yi_mm[6:0]),
                    .rd_out(wmq[c * 256 +: 256]), .w_ce_in(wl_v), .w_addr_in(wl_i[6:0]), .wd_in(wl_d[c * 256 +: 256]),
                    .w_mask_in({256{1'b1}}), .rr_en(2'b00), .rr_addr(14'd0), .cr_en(2'b00), .cr_sel(16'd0));
            end
        end else begin : g_nomem
            assign xmq = {N*32{1'b0}};
            assign wmq = {N*32{1'b0}};
        end
        for (l = 0; l < N; l = l + 1) begin : g_lane
            wire [31:0] xl;
            wire [9:0] f;
            if (HC) begin : g_mix
                ot_dsrom_su_norm_mix_pooln #(.LM(LM), .LA(LA)) u_mix (.clk(clk), .rst_n(rst_n), .v(in_v),
                    .h0(in_x[(0 * N + l) * 32 +: 32]), .h1(in_x[(1 * N + l) * 32 +: 32]),
                    .h2(in_x[(2 * N + l) * 32 +: 32]), .h3(in_x[(3 * N + l) * 32 +: 32]), .pre(pre), .x(xl),
                    .fault(f[0]));
                assign f[6:1] = 6'd0;
            end else begin : g_plain
                assign xl = in_x[l * 32 +: 32];
                assign f[6:0] = 7'd0;
            end
            // the x of the row waits here until the rstd comes back
            wire [31:0] xo;
            assign xl_all[l * 32 +: 32] = xl;
            if (MEM) begin : g_xs
                (* keep *) reg [31:0] xo_r;                // the macro output register
                always @(posedge clk) xo_r <= xmq[l * 32 +: 32];
                assign xo = xo_r;
            end else if (MEMSPLIT) begin : g_xm
                ot_dsrom_su_norm_mem_pooln #(.NV(NV)) u_xb (.clk(clk), .we(x_v), .wa(xi), .wd(xl), .ra(sc_nx), .q(xo));
            end else begin : g_xa
                (* keep *) reg [31:0] xb [0:NV-1];
                (* keep *) reg [31:0] xo_r;
                always @(posedge clk) if (x_v) xb[xi] <= xl;
                always @(posedge clk) xo_r <= xb[sc_nx];
                assign xo = xo_r;
            end
            wire live = (l < LB) || !x_last;          // lanes past D (last vector only) carry +0
            wire [31:0] xs = live ? xl : 32'd0;
            ot_hdc_qmul_lat_pooln #(LM) u_sq (clk, rst_n, x_v, xs, xs, sq[l * 32 +: 32], f[7]);
            // gain ROM and the scale y = bf16(w * (x * r))
            wire [31:0] wo;
            if (MEM) begin : g_ws
                (* keep *) reg [31:0] wo_r;
                always @(posedge clk) wo_r <= wmq[l * 32 +: 32];
                assign wo = wo_r;
            end else if (MEMSPLIT) begin : g_wm
                ot_dsrom_su_norm_mem_pooln #(.NV(NV)) u_wr (.clk(clk), .we(wl_v), .wa(wl_i), .wd(wl_d[l * 32 +: 32]), .ra(yi_m), .q(wo));
            end else begin : g_wa
                (* keep *) reg [31:0] wr [0:NV-1];
                (* keep *) reg [31:0] wo_r;
                always @(posedge clk) if (wl_v) wr[wl_i] <= wl_d[l * 32 +: 32];
                always @(posedge clk) wo_r <= wr[yi_m];
                assign wo = wo_r;
            end
            wire [31:0] p, q;
            ot_hdc_qmul_lat_pooln #(LMS) u_xr (clk, rst_n, sc_go, xo, rh, p, f[8]);
            ot_hdc_qmul_lat_pooln #(LMS) u_w  (clk, rst_n, vy[LMS], wo, p, q, f[9]);
            (* keep *) reg [31:0] yr;
            (* keep *) (* keep *) reg [31:0] yrr;          // the RoPE's copy (its two multipliers), kept through synthesis
            always @(posedge clk) begin yr <= bf16(q); yrr <= bf16(q); end
            assign yb[l * 32 +: 32] = yr;
            assign ybr[l * 32 +: 32] = yrr;
            assign lf[l] = |f;
        end
        // chunk chains: lane 8c+j joins after j-1 adds
        for (c = 0; c < NC; c = c + 1) begin : g_chunk
            wire [31:0] acc [0:7];
            wire [7:0] f;
            assign acc[0] = sq[(8 * c) * 32 +: 32];
            assign f[0] = 1'b0;
            for (k = 1; k < 8; k = k + 1) begin : g_j
                wire [31:0] sd;
                ot_hdc_delay_pooln #(.W(32), .D(LA * (k - 1))) u_sd (.clk(clk), .rst_n(rst_n), .d(sq[(8 * c + k) * 32 +: 32]),
                                                              .q(sd));
                ot_dsrom_qadd_pooln #(.LAT(LA)) u_a (clk, rst_n, vs[LM + LA * (k - 1)], acc[k - 1], sd, acc[k], f[k]);
            end
            assign cs[c * 32 +: 32] = acc[7];
            assign cf[c] = |f;
        end
    endgenerate

    // in-vector tree: level t has NC >> t nodes
    wire [31:0] tv [0:LT][0:NC-1];
    wire [LT:0] tf_any;
    generate
        for (c = 0; c < NC; c = c + 1) begin : g_t0
            assign tv[0][c] = cs[c * 32 +: 32];
        end
        assign tf_any[0] = 1'b0;
        for (k = 1; k <= LT; k = k + 1) begin : g_tl
            wire [(NC >> k)-1:0] f;
            for (c = 0; c < (NC >> k); c = c + 1) begin : g_tn
                ot_dsrom_qadd_pooln #(.LAT(LA)) u_a (clk, rst_n, vs[LM + 7 * LA + LA * (k - 1)], tv[k - 1][2 * c],
                                                           tv[k - 1][2 * c + 1], tv[k][c], f[c]);
            end
            for (c = (NC >> k); c < NC; c = c + 1) begin : g_tz
                assign tv[k][c] = 32'd0;
            end
            assign tf_any[k] = |f;
        end
    endgenerate
    wire        vsum_v = vs[DS];
    wire [31:0] vsum = tv[LT][0];

    // vector levels: heap nodes 1 .. 2 NVP - 1 (root 1), leaves NVP + v.  Node n has height
    // h = log2(NVP) - floor(log2 n); its right child's first leaf is ((2n+1) << (h-1)) - NVP.  Every node has a
    // value pulse (the cycle its value first exists: a leaf's arrival, an add's last stage) and a held copy; an add
    // fires in the cycle its second operand pulses, from the pulse value (no latch on the path).
    wire [31:0] nv [1:2*NVP-1];         // the value: the pulse value in the pulse cycle, the held copy after
    wire        nd [1:2*NVP-1];         // available (pulse or held)
    wire        np [1:2*NVP-1];         // pulse
    wire [NVP:0] nf;                    // add faults of nodes 1 .. NVP-1 (0 and NVP unused)
    assign nf[0] = 1'b0;
    assign nf[NVP] = 1'b0;
    generate
        for (n = NVP; n < 2 * NVP; n = n + 1) begin : g_leaf
            (* keep *) reg [31:0] val;
            (* keep *) reg        vld;
            wire       hit = vsum_v && si == n - NVP;
            always @(posedge clk or negedge rst_n)
                if (!rst_n) vld <= 1'b0;
                else if (go) vld <= 1'b0;
                else if (hit) vld <= 1'b1;
            always @(posedge clk) if (hit) val <= vsum;
            assign np[n] = hit;
            assign nd[n] = vld || hit;
            assign nv[n] = vld ? val : vsum;
        end
        for (n = 1; n < NVP; n = n + 1) begin : g_vn
            localparam integer H = $clog2(NVP) - ($clog2(n + 1) - 1);
            if ((((2 * n + 1) << (H - 1)) - NVP) < NV) begin : g_add      // right child real: an add
                (* keep *) reg st, vld;
                (* keep *) reg [31:0] val;
                wire [LAV:0] av;
                wire [31:0] s;
                wire fire = nd[2 * n] && nd[2 * n + 1] && !st && !go;
                ot_hdc_vline_pooln #(.D(LAV)) u_v (.clk(clk), .rst_n(rst_n), .v(fire), .vd(av));
                ot_dsrom_qadd_pooln #(.LAT(LAV)) u_a (clk, rst_n, fire, nv[2 * n], nv[2 * n + 1], s, nf[n]);
                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin st <= 1'b0; vld <= 1'b0; end
                    else if (go) begin st <= 1'b0; vld <= 1'b0; end
                    else begin
                        if (fire) st <= 1'b1;
                        if (av[LAV]) vld <= 1'b1;
                    end
                end
                always @(posedge clk) if (av[LAV]) val <= s;
                assign np[n] = av[LAV];
                assign nd[n] = vld || av[LAV];
                assign nv[n] = vld ? val : s;
            end else begin : g_pass                                     // right subtree all padding: x + 0 = x
                assign nv[n] = nv[2 * n];
                assign nd[n] = nd[2 * n];
                assign np[n] = np[2 * n];
                assign nf[n] = 1'b0;
            end
        end
    endgenerate
    // the row's sum: the root's pulse
    wire        ss_v = np[1] && !go;
    wire [31:0] ss = nv[1];

    // ---------------------------------------------------------------- result wire, scalar tail, broadcast wire
    wire [32:0] ssw;
    ot_hdc_delay_pooln #(.W(33), .D(RW), .RESET(1)) u_rw (.clk(clk), .rst_n(rst_n), .d({ss_v, ss}), .q(ssw));
    wire [31:0] mq, me, rr;
    wire        mq_v, me_v, rr_v, f_div, f_eps, f_rsq;
    // ss / D: D = DF * 2^DK, DF in {1, 5}: the constant divider (correctly rounded, 8 stages; n_f is D's binary32)
    ot_dsrom_divc #(.F(DF), .K(DK)) u_div (.clk(clk), .rst_n(rst_n), .v(ssw[32]), .x(ssw[31:0]), .y(mq), .vo(mq_v),
                                           .fault(f_div));
    wire [LA:0] ve;
    ot_hdc_vline_pooln #(.D(LA)) u_ve (.clk(clk), .rst_n(rst_n), .v(mq_v), .vd(ve));
    ot_dsrom_qadd_pooln #(.LAT(LA)) u_eps (clk, rst_n, mq_v, mq, eps, me, f_eps);
    assign me_v = ve[LA];
    ot_dsrom_rsqrt_pooln #(.LM(LM), .LA(LA)) u_rsq (.clk(clk), .rst_n(rst_n), .v(me_v), .x(me), .y(rr), .vo(rr_v), .fault(f_rsq));
    assign r_v = rr_v;
    assign r = rr;
    ot_hdc_delay_pooln #(.W(33), .D(BW - 1), .RESET(1)) u_bw (.clk(clk), .rst_n(rst_n), .d({rr_v, rr}), .q(rbw));
    (* keep *) reg rbv;
    generate if (GH != 0) begin : g_gh
        if (RD != 0) begin : g_bad ot_dsrom_su_norm_GH_needs_RD_0 u_trap (); end
        (* keep *) reg rpend;                      // the rstd landed, the gain not yet loaded
        always @(posedge clk or negedge rst_n)
            if (!rst_n) rpend <= 1'b0;
            else rpend <= !go && (rbw[32] || rpend) && !cos_t[0];
        assign rbs = (rbw[32] || rpend) && cos_t[0];
    end else begin : g_nogh
        assign rbs = rbw[32];
    end endgenerate
    always @(posedge clk or negedge rst_n) if (!rst_n) rbv <= 1'b0; else rbv <= rbs;
    always @(posedge clk) if (rbw[32]) rh <= rbw[31:0];
    assign rb_v = rbv;
    assign y_v = vy[DY];
    assign y_i = yi_o;
    assign y = yb;

    // ---------------------------------------------------------------- RoPE tail (forward), BF16
    // The tail is the last RD elements of the row: lanes LB-RD .. LB-1 of the last vector (LB = its length); the
    // other vectors (and lanes) pass with the same delay.  Routed timing: the rotation reads its operands from its own
    // (kept) copy of the scale output register, uses the operand-cut multiplier (LAT 6) and adder (l5x, LAT 5), and
    // selects rotated / passed BEFORE the output register, so_pooln ro leaves a register.
    localparam integer LMR = LM + 1, LAR = (LA >= 5) ? LA : LA + 1;
    localparam integer DRO = RXS + LMR + LAR + 1;
    wire [DRO:0] vr;
    ot_hdc_vline_pooln #(.D(DRO)) u_vr (.clk(clk), .rst_n(rst_n), .v(y_v), .vd(vr));
    wire [7:0] ro_i, ro_im;
    ot_hdc_delay_pooln #(.W(8), .D(DRO)) u_roi (.clk(clk), .rst_n(rst_n), .d(yi_o), .q(ro_i));
    ot_hdc_delay_pooln #(.W(8), .D(DRO - 1)) u_rom (.clk(clk), .rst_n(rst_n), .d(yi_o), .q(ro_im));
    wire last_rm = (ro_im == NV - 1);              // the vector index at the output register's input
    wire [N-1:0] rf;
    generate
        if (RD > 0) begin : g_rope
            for (l = 0; l < N; l = l + 1) begin : g_rl
                if (l >= LB - RD && l < LB) begin : g_rot
                    localparam integer KK = (l - (LB - RD)) / 2;
                    localparam integer ODD = (l - (LB - RD)) % 2;
                    wire [31:0] cc = cos_t[KK * 32 +: 32], sn = sin_t[KK * 32 +: 32];
                    wire [31:0] mine, pair;
                    ot_hdc_delay_pooln #(.W(64), .D(RXS)) u_rx (.clk(clk), .rst_n(rst_n),
                                                         .d({ybr[l * 32 +: 32], ybr[(ODD ? l - 1 : l + 1) * 32 +: 32]}),
                                                         .q({mine, pair}));
                    wire [31:0] pp, qq, rs, dl;
                    wire f0, f1, f2;
                    ot_hdc_qmul_lat_pooln #(LMR) u_p (clk, rst_n, vr[RXS], mine, cc, pp, f0);                             // a*c | b*c
                    ot_hdc_qmul_lat_pooln #(LMR) u_q (clk, rst_n, vr[RXS], pair, ODD ? sn : {~sn[31], sn[30:0]}, qq, f1); // -(b*s) | a*s
                    ot_dsrom_qadd_pooln #(.LAT(LAR)) u_a (clk, rst_n, vr[RXS + LMR], pp, qq, rs, f2);
                    ot_hdc_delay_pooln #(.W(32), .D(DRO - 1)) u_d (.clk(clk), .rst_n(rst_n), .d(yb[l * 32 +: 32]), .q(dl));
                    (* keep *) reg [31:0] o;
                    always @(posedge clk) o <= last_rm ? bf16(rs) : dl;
                    assign ro[l * 32 +: 32] = o;
                    assign rf[l] = vr[DRO] & (ro_i == NV - 1) & (f0 | f1 | f2);
                end else begin : g_keep
                    ot_hdc_delay_pooln #(.W(32), .D(DRO)) u_d (.clk(clk), .rst_n(rst_n), .d(yb[l * 32 +: 32]), .q(ro[l * 32 +: 32]));
                    assign rf[l] = 1'b0;
                end
            end
        end else begin : g_norope
            assign ro = {N * 32{1'b0}};
            assign rf = {N{1'b0}};
        end
    endgenerate
    assign ro_v = (RD > 0) ? vr[DRO] : 1'b0;

    // ---------------------------------------------------------------- FP8 act-quant, one instance a 32-lane block
    wire [N/32:0] qf;
    generate
        if (QUANT) begin : g_q
            wire            qin_v = (RD > 0) ? ro_v : y_v;
            wire [N*32-1:0] qin   = (RD > 0) ? ro : yb;
            wire [7:0]      qin_i = (RD > 0) ? ro_i : yi_o;
            wire [N/32-1:0] vo;
            for (k = 0; k < N / 32; k = k + 1) begin : g_aq
                wire signed [9:0] e;
                ot_dsrom_aq12 u_aq (.clk(clk), .rst_n(rst_n), .v(qin_v), .x(qin[k * 1024 +: 1024]),
                                    .vo(vo[k]), .q(q_codes[k * 256 +: 256]), .e(e), .y(q_y[k * 512 +: 512]),
                                    .fault(qf[k]));
                assign q_e[k * 10 +: 10] = e;
            end
            assign q_v = vo[0];
            ot_hdc_delay_pooln #(.W(8), .D(18)) u_qi (.clk(clk), .rst_n(rst_n), .d(qin_i), .q(q_i));
            assign qf[N / 32] = 1'b0;
        end else begin : g_nq
            assign q_v = 1'b0;
            assign q_i = 8'd0;
            assign q_codes = 256'd0;
            assign q_e = 10'd0;
            assign q_y = 512'd0;
            assign qf = {(N / 32 + 1){1'b0}};
        end
    endgenerate

    // ---------------------------------------------------------------- faults (sticky)
    wire f_any;
    generate if (FREG) begin : g_freg
        (* keep *) reg [N-1:0] lf_r, rf_r;
        (* keep *) reg [8:0]   fg;
        always @(posedge clk or negedge rst_n)
            if (!rst_n) begin lf_r <= {N{1'b0}}; rf_r <= {N{1'b0}}; fg <= 9'd0; end
            else if (go) begin lf_r <= {N{1'b0}}; rf_r <= {N{1'b0}}; fg <= 9'd0; end
            else begin
                lf_r <= lf;
                rf_r <= rf;
                fg   <= {|lf_r, |cf, |tf_any, |nf, f_div, f_eps, f_rsq, |rf_r, |qf};
            end
        assign f_any = |fg;
    end else begin : g_fcomb
        assign f_any = (|lf) || (|cf) || (|tf_any) || (|nf) || f_div || f_eps || f_rsq || (|rf) || (|qf);
    end endgenerate
    (* keep *) reg flt;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) flt <= 1'b0;
        else if (go) flt <= 1'b0;
        else if (f_any) flt <= 1'b1;
    assign fault = flt;
endmodule


// One lane of the hc_pre mix: x = bf16(((h0*p0 + h1*p1) + h2*p2) + h3*p3), the golden's seqsum order; depth
// LM + 3 LA + 1.  Its own module so_pooln it is also a routable minimum component.
module ot_dsrom_su_norm_mix_pooln #(
    parameter integer LM = 5,
    parameter integer LA = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         v,
    input  wire [31:0]  h0, h1, h2, h3,
    input  wire [127:0] pre,
    output wire [31:0]  x,
    output wire         fault
);
    localparam integer DM = LM + 3 * LA + 1;
    wire [DM:0] vm;
    ot_hdc_vline_pooln #(.D(DM)) u_vm (.clk(clk), .rst_n(rst_n), .v(v), .vd(vm));
    wire [31:0] m0, m1, m2, m3, m2d, m3d, a1, a2, a3;
    wire [6:0] f;
    ot_hdc_qmul_lat_pooln #(LM) u_m0 (clk, rst_n, v, h0, pre[0 +: 32], m0, f[0]);
    ot_hdc_qmul_lat_pooln #(LM) u_m1 (clk, rst_n, v, h1, pre[32 +: 32], m1, f[1]);
    ot_hdc_qmul_lat_pooln #(LM) u_m2 (clk, rst_n, v, h2, pre[64 +: 32], m2, f[2]);
    ot_hdc_qmul_lat_pooln #(LM) u_m3 (clk, rst_n, v, h3, pre[96 +: 32], m3, f[3]);
    ot_dsrom_qadd_pooln #(.LAT(LA)) u_a1 (clk, rst_n, vm[LM], m0, m1, a1, f[4]);
    ot_hdc_delay_pooln #(.W(32), .D(LA)) u_d2 (.clk(clk), .rst_n(rst_n), .d(m2), .q(m2d));
    ot_dsrom_qadd_pooln #(.LAT(LA)) u_a2 (clk, rst_n, vm[LM + LA], a1, m2d, a2, f[5]);
    ot_hdc_delay_pooln #(.W(32), .D(2 * LA)) u_d3 (.clk(clk), .rst_n(rst_n), .d(m3), .q(m3d));
    ot_dsrom_qadd_pooln #(.LAT(LA)) u_a3 (clk, rst_n, vm[LM + 2 * LA], a2, m3d, a3, f[6]);
    (* keep *) reg [31:0] xr;
    wire [32:0] rs = {1'b0, a3} + 33'h7FFF + {32'd0, a3[16]};    // RNE to BF16 (tools/hdc_golden.to_bf16)
    always @(posedge clk) xr <= {rs[31:16], 16'd0};
    assign x = xr;
    assign fault = |f;
endmodule


// ot_hdc_v41x_rsqrt_pooln (rtl/hdc/v41x/ot_hdc_v41x_sfu.sv), verbatim but for its add, which is ot_dsrom_qadd_pooln so_pooln the
// fused 1.2 GHz pipeline can take the LAT-6 adder (ot_hdc_qadd_lat_pooln maps LAT 6 to the serial-domain adder).  Same
// Newton steps, same constants, DEPTH 1 + 3 (3 LM + LA).
module ot_dsrom_rsqrt_pooln #(
    parameter integer LM = 3,                   // multiplier latency (ot_hdc_qmul_lat_pooln)
    parameter integer LA = 3                    // add latency (ot_hdc_qadd_lat_pooln: 3, or 4 input cut)
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    output wire [31:0] y,
    output wire        vo,
    output wire        fault
);
    localparam integer IT = 3 * LM + LA;
    localparam integer DEPTH = 1 + 3 * IT;      // 37 (LM 3), 46 (LM 4)
    wire [DEPTH:0] vd;
    ot_hdc_vline_pooln #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    (* keep *) reg [31:0] y0;
    wire [31:0] y0_n;
    wire        unused_cy;
    ot_hdc_kadd_pooln #(.W(32), .K((LM != 3 || LA != 3) ? 1 : 0)) u_y0 (.a(32'h5F3759DF), .b(~{1'b0, x[31:1]}), .cin(1'b1), .s(y0_n),
                                                      .cout(unused_cy));
    always @(posedge clk) y0 <= y0_n;
    wire [31:0] half;
    wire [31:0] hd [0:2];
    wire [31:0] yi [0:3];
    wire [31:0] yy [0:2];
    wire [31:0] hm [0:2];
    wire [31:0] s [0:2];
    wire [31:0] yd [0:2];
    wire [12:0] f;
    ot_hdc_qmul_lat_pooln #(LM) m_half (clk, rst_n, v, x, 32'h3F000000, half, f[12]);   // LM
    ot_hdc_delay_pooln #(.W(32), .D(1)) d_h0 (clk, rst_n, half, hd[0]);       // 1 + LM
    assign yi[0] = y0;
    genvar k;
    generate
        for (k = 0; k < 3; k = k + 1) begin : g_nr
            if (k < 2) begin : g_h
                ot_hdc_delay_pooln #(.W(32), .D(IT)) d_h (clk, rst_n, hd[k], hd[k+1]);
            end
            ot_hdc_qmul_lat_pooln #(LM) m_yy (clk, rst_n, vd[1 + IT*k],             yi[k], yi[k], yy[k], f[4*k]);
            ot_hdc_qmul_lat_pooln #(LM) m_hm (clk, rst_n, vd[1 + IT*k + LM],        hd[k], yy[k], hm[k], f[4*k+1]);
            ot_dsrom_qadd_pooln #(.LAT(LA)) a_s  (clk, rst_n, vd[1 + IT*k + 2*LM],      32'h3FC00000, {~hm[k][31], hm[k][30:0]}, s[k], f[4*k+2]);
            ot_hdc_delay_pooln #(.W(32), .D(2*LM + LA)) d_y (clk, rst_n, yi[k], yd[k]);
            ot_hdc_qmul_lat_pooln #(LM) m_y  (clk, rst_n, vd[1 + IT*k + 2*LM + LA], yd[k], s[k], yi[k+1], f[4*k+3]);
        end
    endgenerate
    assign y = yi[3];
    assign fault = |f;
endmodule

// ot_dsrom_qadd_pooln #(LAT): the binary32 add of the fused pipelines.  LAT 6: ot_dsrom_fp32_add_f12_l6_pooln; otherwise the
// keep-prefix ot_hdc_qadd_lat_pooln (LAT 4: f12_l4, LAT 5: f12_l5x through rtl/hdc/ot_hdc_fastfp_lat_f12.sv).
module ot_dsrom_qadd_pooln #(parameter integer LAT = 4) (
    input wire clk, input wire rst_n, input wire v, input wire [31:0] a, input wire [31:0] b, output wire [31:0] y,
    output wire fault
);
    generate if (LAT == 6) begin : g6
        wire [1:0] err;
        wire vo;
        ot_dsrom_fp32_add_f12_l6_pooln u (.clk(clk), .rst_n(rst_n), .valid_in(v), .a(a), .b(b), .y(y), .err(err), .valid_out(vo));
        assign fault = vo && (err != 2'd0);
    end else begin : gq
        ot_hdc_qadd_lat_pooln #(.KEEP(1), .LAT(LAT)) u (clk, rst_n, v, a, b, y, fault);
    end endgenerate
endmodule

// One lane's NV-word store with a registered read, as its own kept hierarchy (MEMSPLIT=1 only): a 64-lane engine
// then synthesises this array once instead of 128 flat NV x 32 dynamically indexed register files.
(* keep_hierarchy = "yes" *)
module ot_dsrom_su_norm_mem_pooln #(parameter integer NV = 8) (
    input  wire clk, we,
    input  wire [7:0] wa, ra,
    input  wire [31:0] wd,
    (* keep *) output reg  [31:0] q
);
    (* keep *) reg [31:0] m [0:NV-1];
    always @(posedge clk) if (we) m[wa] <= wd;
    always @(posedge clk) q <= m[ra];
endmodule
